# Chapter 19 Thermal physics — 19.1 to 19.6. Sign convention (9702): ΔU = q + w, w = work done ON the system.
LF, LV, CW, CICE = 3.34e5, 2.26e6, 4200, 2100
WATER = ' Take the specific heat capacity of water as 4200 J kg⁻¹ K⁻¹.'
FUSION = ' Take the specific latent heat of fusion of ice as 3.34 × 10⁵ J kg⁻¹.'
VAPOUR = ' Take the specific latent heat of vaporisation of water as 2.26 × 10⁶ J kg⁻¹.'

# ═════════════════════════ 19.1 Changes of state (16/17/11) ═════════════════════════
lesson('19.1')
M('E', 1, 'What happens to the mean kinetic energy of the molecules of a pure substance while it is melting at constant temperature?', 'It stays the same', ['It increases', 'It decreases', 'It becomes zero'],
  'Temperature measures the mean kinetic energy of the molecules. While melting the temperature is constant, so the mean Ek is constant; the energy supplied increases the potential energy (breaking bonds).')
M('E', 1, 'Energy is supplied to boiling water but its temperature stays at 100 °C. Where does the energy go?', 'Into increasing the potential energy of the molecules as they separate', ['Into increasing the kinetic energy of the molecules', 'It is destroyed', 'Into heating the container only'], 'During a change of state the energy breaks intermolecular bonds, increasing molecular potential energy, not kinetic energy.')
M('E', 1, 'Which describes evaporation?', 'The escape of the most energetic molecules from the surface of a liquid at any temperature', ['The formation of bubbles throughout a liquid at its boiling point', 'The change from gas to liquid', 'The melting of a solid at its surface'], 'Evaporation happens only at the surface and at any temperature; boiling happens throughout at one temperature.')
M('E', 1, 'Why does evaporation cool the liquid left behind?', 'The fastest molecules leave, so the mean kinetic energy of those left decreases', ['The liquid absorbs energy from the air', 'The molecules left behind gain potential energy', 'The pressure above the liquid rises'], 'Losing the highest-energy molecules lowers the average kinetic energy of the remaining ones, so the temperature falls.')
N('E', 2, 'A 2.5 kg block of ice taken from a cold store at its melting point is left to turn completely into water at 0 °C. How much energy does it absorb from the room?' + FUSION, 2.5 * LF, 'J', f'E = mL_f = 2.5 × 3.34 × 10⁵ = {sf(2.5 * LF)} J', ['C1: E = mL'], aq='E')
N('E', 2, 'How much energy must a kettle supply to turn 0.40 kg of boiling water at 100 °C completely into steam?' + VAPOUR, 0.40 * LV, 'J', f'E = mL_v = 0.40 × 2.26 × 10⁶ = {sf(0.4 * LV)} J', ['C1: E = mL'], aq='E')
N('E', 2, 'A freezer removes 6.68 × 10⁴ J from water at 0 °C, freezing it completely. What mass of ice is formed?' + FUSION, 6.68e4 / LF, 'kg', f'm = E/L_f = 6.68 × 10⁴ ÷ 3.34 × 10⁵ = {sf(6.68e4 / LF)} kg', ['C1: m = E/L'], aq='m')
M('E', 1, 'What is the specific latent heat of vaporisation of a substance?', 'The energy needed to change 1 kg of liquid into vapour at constant temperature', ['The energy needed to raise 1 kg of liquid by 1 K', 'The energy needed to melt 1 kg of solid', 'The energy released when 1 kg of vapour cools by 1 K'], 'L_v = E/m for the liquid → gas change at its boiling point, without a temperature change.')
M('E', 1, 'A hot sauna stone is splashed with water and steam forms. Which process releases energy?', 'Steam condensing on a person\'s skin', ['Water evaporating from the stone', 'Ice melting', 'Water boiling on the stone'], 'Condensation releases the latent heat of vaporisation, which is why steam scalds more than water at 100 °C.')
N('E', 1, 'A 1.2 kW heater melts a block of wax at its melting point in 150 s. How much energy is supplied?', 1200 * 150, 'J', 'E = Pt = 1200 × 150 = 1.8 × 10⁵ J', [], sig=2, aq='E')
M('E', 1, 'On a temperature–time graph for a substance heated at a steady rate, what does a horizontal section show?', 'A change of state', ['The substance is cooling', 'The specific heat capacity is zero', 'No energy is being supplied'], 'Energy is still being supplied, but it goes into changing the state, so the temperature stays constant.')
M('E', 1, 'Why is more energy needed to boil 1 kg of water than to melt 1 kg of ice?', 'Boiling separates the molecules completely and pushes back the atmosphere; melting only loosens the bonds', ['Water has a higher temperature', 'Ice has more molecules per kg', 'Melting needs no energy'], 'In vaporisation all bonds are broken and work is done against the atmosphere, so L_v ≫ L_f.')
N('E', 2, 'A blacksmith quenches hot iron, and 0.15 kg of water at 100 °C boils away. How much energy did the water absorb in boiling?' + VAPOUR, 0.15 * LV, 'J', f'E = mL_v = 0.15 × 2.26 × 10⁶ = {sf(0.15 * LV)} J', ['C1: E = mL_v'], aq='E')
N('E', 2, 'Solid lead at its melting point needs 4.6 × 10³ J to melt 0.20 kg. Calculate the specific latent heat of fusion of lead.', 4.6e3 / 0.20, 'J kg⁻¹', 'L = E/m = 4.6 × 10³ ÷ 0.20 = 2.3 × 10⁴ J kg⁻¹', ['C1: L = E/m'], sig=2, aq='L')
M('E', 1, 'Which change of state releases energy to the surroundings?', 'Freezing', ['Melting', 'Boiling', 'Evaporation'], 'Freezing releases the latent heat of fusion as bonds form.')
N('E', 2, 'An ice cube of mass 25 g at 0 °C melts in a drink. How much energy does it absorb in melting?' + FUSION, 0.025 * LF, 'J', f'E = mL = 0.025 × 3.34 × 10⁵ = {sf(0.025 * LF)} J', ['C1: mass in kg'], aq='E')
# medium
N('M', 3, 'Calculate the total energy needed to turn 0.50 kg of ice at −10 °C into water at 0 °C. The specific heat capacity of ice is 2100 J kg⁻¹ K⁻¹.' + FUSION, 0.5 * CICE * 10 + 0.5 * LF, 'J',
  f'Warm the ice: 0.50 × 2100 × 10 = {sf(0.5 * 2100 * 10)} J. Melt it: 0.50 × 3.34 × 10⁵ = {sf(0.5 * LF)} J. Total = {sf(0.5 * 2100 * 10, 4)} + {sf(0.5 * LF, 4)} = {sf(0.5 * CICE * 10 + 0.5 * LF)} J',
  ['C1: mcΔθ for ice', 'C1: mL_f', 'C1: total'], aq='E')
N('M', 4, 'A 2.0 kW kettle contains 0.80 kg of water at 100 °C. The kettle fails to switch off. Calculate how long it takes to boil away half the water, assuming all the energy goes to the water.' + VAPOUR, 0.40 * LV / 2000, 's',
  f'Mass boiled = 0.40 kg. E = mL_v = 0.40 × 2.26 × 10⁶ = {sf(0.4 * LV)} J. t = E/P = {sf(0.4 * LV)} ÷ 2000 = {sf(0.4 * LV / 2000)} s',
  ['C1: half the mass', 'C1: E = mL_v', 'C1: t = E/P'], aq='t')
N('M', 3, 'Steam at 100 °C condenses on a cold window and the water formed cools to 20 °C. Calculate the energy released per kilogram of steam.' + VAPOUR + WATER, LV + CW * 80, 'J',
  f'Condensing: 2.26 × 10⁶ J. Cooling 1 kg of water by 80 K: 4200 × 80 = {sf(4200 * 80)} J. Total = 2.26 × 10⁶ + {sf(4200 * 80, 4)} = {sf(LV + CW * 80)} J',
  ['C1: latent heat released', 'C1: mcΔθ for cooling', 'C1: total'], aq='E')
M('M', 3, 'Why does a scald from steam at 100 °C do much more damage than one from water at 100 °C?', 'Condensing steam releases its large latent heat to the skin before cooling', ['Steam is hotter than 100 °C', 'Steam molecules are larger', 'Water absorbs energy from skin'], 'Each kg of steam gives out 2.26 MJ as it condenses, in addition to the energy released as the water cools.', ['C1: latent heat released on condensing', 'C1: large compared with cooling'])
N('M', 3, 'A student melts ice with a 60 W immersion heater. In 5.0 minutes, 0.052 kg of ice melts (allow for the ice melting due to the room by subtracting nothing). Calculate the specific latent heat of fusion found by the student.', 60 * 300 / 0.052, 'J kg⁻¹',
  f'E = Pt = 60 × 300 = 18000 J. L = E/m = 18000 ÷ 0.052 = {sf(18000 / 0.052)} J kg⁻¹', ['C1: E = Pt', 'C1: t in s', 'C1: L = E/m'], aq='L')
M('M', 4, 'In an experiment to measure L_f, a control funnel with no heater collects 8 g of melted ice in the same time as the heated funnel collects 52 g. Why is the control used?', 'To subtract the ice melted by energy from the room, so only the heater\'s energy is counted', ['To measure the heater\'s power', 'To keep the room cold', 'To increase the mass of ice'], 'The heater melted 52 − 8 = 44 g; using 52 g would give too small a value of L_f.', ['C1: room melts some ice', 'C1: subtract control mass', 'C1: gives heater-only melting'])
N('M', 3, 'In the experiment above, the heater supplied 15 000 J. The heated funnel collected 52 g and the control collected 8 g. Calculate L_f.', 15000 / 0.044, 'J kg⁻¹', 'm = 0.052 − 0.008 = 0.044 kg. L = E/m = 15000 ÷ 0.044 = 3.41 × 10⁵ J kg⁻¹', ['C1: corrected mass', 'C1: L = E/m', 'C1: units'], aq='L')
N('M', 4, 'Liquid nitrogen boils at 77 K with L_v = 2.0 × 10⁵ J kg⁻¹. A 25 W heater is placed in a flask of liquid nitrogen. Calculate the mass that boils away in 10 minutes.', 25 * 600 / 2.0e5, 'kg', 'E = Pt = 25 × 600 = 15000 J. m = E/L = 15000 ÷ 2.0 × 10⁵ = 0.075 kg', ['C1: E = Pt', 'C1: m = E/L', 'C1: t in s'], sig=2, aq='m')
M('M', 3, 'A temperature–time graph for a liquid cooling to a solid shows a horizontal section at 54 °C. What can be concluded?', 'The substance freezes at 54 °C, releasing latent heat that balances the loss to the surroundings', ['The substance has stopped losing energy', 'The specific heat capacity becomes infinite', 'The thermometer has failed'], 'While freezing, the latent heat released keeps the temperature constant even though energy is still lost.', ['C1: freezing point', 'C1: latent heat released'])
N('M', 3, 'A 500 W electric heater is used to vaporise water already at 100 °C. In 4.0 minutes the mass of water falls by 50 g. Calculate L_v from these results.', 500 * 240 / 0.050, 'J kg⁻¹', 'E = Pt = 500 × 240 = 1.2 × 10⁵ J. L_v = E/m = 1.2 × 10⁵ ÷ 0.050 = 2.4 × 10⁶ J kg⁻¹', ['C1: E = Pt', 'C1: L = E/m'], sig=2, aq='L_v')
M('M', 3, 'The value of L_v found in a simple heating experiment is usually larger than the accepted value. Why?', 'Some of the heater\'s energy is lost to the surroundings, so less water boils than expected', ['The thermometer reads too high', 'Water has a low specific heat capacity', 'Steam condenses back into the beaker'], 'Energy lost means the measured mass loss is too small for the energy counted, giving L = E/m too large.', ['C1: energy lost', 'C1: m too small, L too large'])
N('M', 4, 'Sweat evaporates from an athlete at 0.50 kg per hour. The latent heat of vaporisation of sweat at skin temperature is 2.4 × 10⁶ J kg⁻¹. Calculate the cooling power provided.', 0.50 * 2.4e6 / 3600, 'W', 'Energy per hour = 0.50 × 2.4 × 10⁶ = 1.2 × 10⁶ J. P = 1.2 × 10⁶ ÷ 3600 = 333 W', ['C1: E = mL', 'C1: per second', 'C1: P = E/t'], aq='P')
N('M', 3, 'An ice cube tray holds 0.30 kg of water at 0 °C. The freezer extracts energy at 40 W. How long does it take to freeze all the water?' + FUSION, 0.30 * LF / 40, 's', f'E = mL = 0.30 × 3.34 × 10⁵ = {sf(0.3 * LF)} J. t = E/P = {sf(0.3 * LF)} ÷ 40 = {sf(0.3 * LF / 40)} s', ['C1: E = mL', 'C1: t = E/P'], aq='t')
M('M', 3, 'Why does a pressure cooker cook food faster?', 'Higher pressure raises the boiling point of the water, so the food is at a higher temperature', ['It lowers the latent heat', 'Steam is cooler under pressure', 'It reduces the specific heat capacity'], 'At about 2 atm water boils at about 120 °C, so the food cooks faster.', ['C1: boiling point rises with pressure', 'C1: higher cooking temperature'])
N('M', 4, 'A 0.20 kg block of ice at 0 °C is dropped into 0.80 kg of water at 30 °C in an insulated flask. Calculate the energy the water can give up in cooling to 0 °C, and decide whether all the ice melts. Give that energy.' + WATER + FUSION, 0.80 * CW * 30, 'J',
  f'Energy available = 0.80 × 4200 × 30 = {sf(0.8 * 4200 * 30)} J. Energy to melt the ice = 0.20 × 3.34 × 10⁵ = {sf(0.2 * LF)} J. Available > needed, so all the ice melts.',
  ['C1: mcΔθ for water', 'C1: mL for ice', 'B1: comparison'], aq='E')
N('M', 3, 'An electric heater raises 0.20 kg of a solid to its melting point and then melts it, using 1.04 × 10⁵ J in total. The heating to the melting point needed 3.6 × 10⁴ J. Calculate the specific latent heat of fusion.', (1.04e5 - 3.6e4) / 0.20, 'J kg⁻¹', 'Energy to melt = 1.04 × 10⁵ − 3.6 × 10⁴ = 6.8 × 10⁴ J. L = 6.8 × 10⁴ ÷ 0.20 = 3.4 × 10⁵ J kg⁻¹', ['C1: subtract heating energy', 'C1: L = E/m'], sig=2, aq='L')
# hard
N('H', 6, '0.050 kg of ice at −15 °C is put into a glass containing 0.25 kg of lemonade (treat as water) at 24 °C. Ignore the glass and surroundings. c_ice = 2100 J kg⁻¹ K⁻¹. (a) Calculate the energy needed to warm the ice to 0 °C and melt it. (b) Write an equation for the final temperature θ. (c) Calculate θ. Give only the answer to (c).' + WATER + FUSION,
  (0.25 * CW * 24 - 0.05 * CICE * 15 - 0.05 * LF) / ((0.25 + 0.05) * CW), '°C',
  f'(a) 0.050 × 2100 × 15 + 0.050 × 3.34 × 10⁵ = {sf(0.05 * 2100 * 15)} + {sf(0.05 * LF)} = {sf(0.05 * 2100 * 15 + 0.05 * LF)} J. (b) Energy lost by lemonade = energy gained by ice: 0.25 × 4200 × (24 − θ) = {sf(0.05 * 2100 * 15 + 0.05 * LF, 4)} + 0.050 × 4200 × θ. (c) 25200 − 1050θ = {sf(0.05 * 2100 * 15 + 0.05 * LF, 4)} + 210θ, so θ = (25200 − {sf(0.05 * 2100 * 15 + 0.05 * LF, 4)}) ÷ 1260 = {sf((0.25 * CW * 24 - 0.05 * CICE * 15 - 0.05 * LF) / ((0.3) * CW))} °C',
  ['C1: ice warming', 'C1: ice melting', 'A1: total for (a)', 'M1: energy balance including melted ice warming', 'C1: rearranged', 'A1: θ'], aq='θ')
N('H', 5, 'A 3.0 kW kettle holds 1.2 kg of water at 20 °C. (a) Calculate the time to bring it to 100 °C. (b) The kettle is left on for a further 2.0 minutes. Calculate the mass of water boiled away. (c) Suggest why the real mass lost is a little less. Give only the answer to (b).' + WATER + VAPOUR, 3000 * 120 / LV, 'kg',
  f'(a) E = mcΔθ = 1.2 × 4200 × 80 = {sf(1.2 * 4200 * 80)} J, t = E/P = {sf(1.2 * 4200 * 80)} ÷ 3000 = {sf(1.2 * 4200 * 80 / 3000)} s. (b) E = Pt = 3000 × 120 = 3.6 × 10⁵ J, m = E/L_v = 3.6 × 10⁵ ÷ 2.26 × 10⁶ = {sf(3.6e5 / LV)} kg. (c) Some energy is lost to the surroundings and the kettle body, so less is available to boil water.',
  ['C1: mcΔθ', 'A1: t', 'C1: E = Pt', 'A1: m', 'B1: energy losses'], aq='m')
N('H', 6, 'A student heats 0.40 kg of a solid wax at a steady 50 W and records its temperature every minute: 20, 32, 44, 52, 52, 52, 52, 52, 60, 68 °C at t = 0, 1, …, 9 min. (a) State the melting point. (b) Use the time the temperature is constant to calculate L_f. (c) Use the first three minutes to calculate the specific heat capacity of the solid wax. Give only the answer to (b).', 50 * 5 * 60 / 0.40, 'J kg⁻¹',
  f'(a) 52 °C. (b) Constant from about t = 3 to t = 8 min: 5 minutes. E = Pt = 50 × 300 = 15000 J, L = E/m = 15000 ÷ 0.40 = {sf(15000 / 0.4)} J kg⁻¹. (c) In 2 min (120 s) the temperature rises 24 K: c = Pt/(mΔθ) = 50 × 120 ÷ (0.40 × 24) = {sf(6000 / 9.6)} J kg⁻¹ K⁻¹',
  ['B1: 52 °C', 'C1: duration of plateau', 'C1: E = Pt', 'A1: L', 'C1: c = Pt/mΔθ', 'A1: c'], aq='L')
N('H', 5, 'A climber melts snow at −8.0 °C to make 1.5 kg of water at 60 °C for tea, using a gas stove. c_ice = 2100 J kg⁻¹ K⁻¹. (a) Calculate the energy to warm the snow to 0 °C. (b) Calculate the total energy needed. (c) Only 40 % of the stove\'s energy reaches the pan. Calculate the energy the gas must release. Give only the answer to (c).' + WATER + FUSION, (1.5 * CICE * 8 + 1.5 * LF + 1.5 * CW * 60) / 0.40, 'J',
  f'(a) 1.5 × 2100 × 8.0 = {sf(1.5 * 2100 * 8)} J. (b) + 1.5 × 3.34 × 10⁵ + 1.5 × 4200 × 60: total = {sf(1.5 * CICE * 8 + 1.5 * LF + 1.5 * CW * 60)} J. (c) E = {sf(1.5 * CICE * 8 + 1.5 * LF + 1.5 * CW * 60, 4)} ÷ 0.40 = {sf((1.5 * CICE * 8 + 1.5 * LF + 1.5 * CW * 60) / 0.4)} J',
  ['A1: warming snow', 'C1: melting', 'C1: warming water', 'A1: total', 'A1: ÷ efficiency'], aq='E')
N('H', 6, 'Boiling water in an insulated flask is kept at 100 °C by an electric heater, and the rate of mass loss is measured. At 120 W the mass decreases at 4.6 × 10⁻⁵ kg s⁻¹; at 200 W it decreases at 8.2 × 10⁻⁵ kg s⁻¹. (a) Explain why two powers are used. (b) Write P = L_v(dm/dt) + h for each, where h is the rate of heat loss. (c) Solve for L_v. Give only the answer to (c).', (200 - 120) / (8.2e-5 - 4.6e-5), 'J kg⁻¹',
  f'(a) Heat is lost to the surroundings at a rate h that is the same at both powers (same temperature), so it can be eliminated. (b) 120 = L_v × 4.6 × 10⁻⁵ + h and 200 = L_v × 8.2 × 10⁻⁵ + h. (c) Subtracting: 80 = L_v × 3.6 × 10⁻⁵, L_v = 80 ÷ 3.6 × 10⁻⁵ = {sf(80 / 3.6e-5)} J kg⁻¹',
  ['B1: losses the same at the same temperature', 'B1: eliminate h', 'C1: two equations', 'M1: subtract', 'C1: rearranged', 'A1: L_v'], aq='L_v')

# ═════════════════════════ 19.2 The first law of thermodynamics (17/15/10) ═════════════════════════
lesson('19.2')
M('E', 1, 'In ΔU = q + w, what does q represent?', 'The energy transferred to the system by heating', ['The work done by the system', 'The internal energy', 'The temperature change'], 'q is the thermal energy supplied to the system; w is the work done on it; ΔU is the increase in internal energy.')
M('E', 1, 'A gas expands and does work on its surroundings. In ΔU = q + w, what is the sign of w?', 'Negative', ['Positive', 'Zero', 'It depends on the temperature'], 'w is the work done ON the gas. When the gas expands it does work on the surroundings, so w is negative.')
N('E', 2, 'A gas is heated with 750 J of energy and 300 J of work is done on it. Calculate the increase in its internal energy.', 1050, 'J', 'ΔU = q + w = 750 + 300 = 1050 J', ['C1: ΔU = q + w with signs'], aq='ΔU')
N('E', 2, 'A gas absorbs 400 J by heating while doing 150 J of work on its surroundings. Calculate ΔU.', 250, 'J', 'w = −150 J. ΔU = q + w = 400 + (−150) = 250 J', ['C1: w negative for work done by gas'], sig=2, aq='ΔU')
N('E', 2, 'A gas expands at a constant pressure of 2.0 × 10⁵ Pa, increasing its volume by 3.0 × 10⁻³ m³. Calculate the work done by the gas.', 2.0e5 * 3.0e-3, 'J', 'W = pΔV = 2.0 × 10⁵ × 3.0 × 10⁻³ = 600 J', ['C1: W = pΔV'], sig=2, aq='W')
M('E', 1, 'Which principle does the first law of thermodynamics express?', 'Conservation of energy', ['Conservation of momentum', 'Conservation of mass', 'The tendency of energy to spread out'], 'The increase in internal energy equals the energy supplied by heating plus the work done on the system.')
N('E', 2, 'A bicycle pump does 80 J of work compressing the air inside it so quickly that no heat escapes. What is the change in internal energy of the air?', 80, 'J', 'q = 0, w = +80 J, so ΔU = 0 + 80 = 80 J (the air warms up)', ['C1: q = 0'], sig=2, aq='ΔU')
M('E', 1, 'A gas expands without any heat entering or leaving (adiabatically). What happens to its internal energy?', 'It decreases, because the gas does work', ['It increases', 'It stays the same', 'It becomes zero'], 'q = 0 and w < 0, so ΔU = w < 0: the gas cools.')
N('E', 2, 'Calculate the work done on a gas when it is compressed at a constant pressure of 1.2 × 10⁵ Pa from 4.0 × 10⁻³ m³ to 2.5 × 10⁻³ m³.', 1.2e5 * 1.5e-3, 'J', 'W = pΔV = 1.2 × 10⁵ × (4.0 − 2.5) × 10⁻³ = 180 J done on the gas', ['C1: W = p × volume decrease'], sig=2, aq='W')
M('E', 1, 'An ideal gas is taken round a complete cycle back to its starting state. What is the total change in its internal energy?', 'Zero', ['Equal to the heat supplied', 'Equal to the work done', 'It cannot be determined'], 'Internal energy depends only on the state (for an ideal gas, only on temperature). Back at the start, ΔU = 0.')
N('E', 2, 'A gas loses 500 J by heating to its surroundings while 200 J of work is done on it. Calculate ΔU.', -300, 'J', 'q = −500 J, w = +200 J. ΔU = −500 + 200 = −300 J', ['C1: signs of q and w'], sig=2, sign=True, aq='ΔU')
M('E', 1, 'For an ideal gas kept at constant temperature, what is ΔU?', 'Zero', ['Equal to q', 'Equal to −q', 'Positive'], 'The internal energy of an ideal gas depends only on its temperature, so at constant temperature ΔU = 0 and q = −w.')
N('E', 2, 'A gas at constant temperature does 350 J of work as it expands. How much energy was supplied to it by heating?', 350, 'J', 'ΔU = 0, so q = −w = −(−350) = 350 J', ['C1: ΔU = 0 at constant T'], sig=2, aq='q')
M('E', 1, 'Which unit is correct for pΔV?', 'J', ['Pa', 'N', 'W'], 'Pa × m³ = N m⁻² × m³ = N m = J.')
N('E', 2, 'A gas in a cylinder expands at a pressure of 1.0 × 10⁵ Pa. The piston of area 0.020 m² moves out 0.15 m. Calculate the work done by the gas.', 1.0e5 * 0.020 * 0.15, 'J', 'ΔV = A × d = 0.020 × 0.15 = 3.0 × 10⁻³ m³. W = pΔV = 1.0 × 10⁵ × 3.0 × 10⁻³ = 300 J', ['C1: ΔV = Ad, W = pΔV'], sig=2, aq='W')
M('E', 1, 'A balloon of air is placed in a freezer. Its volume decreases and it loses energy by heating. Which is correct?', 'q is negative and w is positive', ['q is positive and w is positive', 'q is negative and w is negative', 'q and w are both zero'], 'Energy leaves by heating (q < 0); the surroundings do work compressing the air (w > 0).')
N('E', 2, 'A gas is heated with 1.2 kJ of energy at constant volume. Calculate the increase in its internal energy.', 1200, 'J', 'At constant volume no work is done (w = 0), so ΔU = q + w = 1200 + 0 = 1200 J', ['C1: w = 0 at constant volume'], sig=2, aq='ΔU')
# medium
N('M', 3, 'A gas at a constant pressure of 1.5 × 10⁵ Pa is heated with 900 J and expands from 2.0 × 10⁻³ m³ to 4.0 × 10⁻³ m³. Calculate the change in its internal energy.', 900 - 1.5e5 * 2.0e-3, 'J',
  'Work done by gas = pΔV = 1.5 × 10⁵ × 2.0 × 10⁻³ = 300 J, so w = −300 J. ΔU = q + w = 900 − 300 = 600 J', ['C1: pΔV', 'C1: w negative', 'C1: ΔU = q + w'], sig=2, aq='ΔU')
N('M', 4, 'A gas is compressed at a constant 3.0 × 10⁵ Pa from 0.050 m³ to 0.035 m³ while losing 2500 J by heating. Calculate ΔU.', 3.0e5 * 0.015 - 2500, 'J',
  'w = +pΔV = 3.0 × 10⁵ × 0.015 = 4500 J. q = −2500 J. ΔU = −2500 + 4500 = 2000 J', ['C1: volume change 0.015 m³', 'C1: w positive (compression)', 'C1: q negative', ], sig=2, aq='ΔU')
M('M', 3, 'A gas undergoes an isothermal expansion. Which statement is correct?', 'The heat supplied equals the work done by the gas', ['The heat supplied is zero', 'The internal energy increases', 'The work done is zero'], 'Isothermal: ΔU = 0, so q = −w: all the heat supplied is used to do work.', ['C1: ΔU = 0', 'C1: q = −w'])
N('M', 3, 'In a diesel engine, air is compressed so fast that it is effectively adiabatic. 400 J of work is done on the air, which has 0.020 mol. Calculate the rise in internal energy, and explain why the air becomes hot. Give the rise.', 400, 'J', 'q = 0 (adiabatic), so ΔU = q + w = 0 + 400 = 400 J. The molecules\' mean kinetic energy increases, so the temperature rises enough to ignite the fuel.', ['C1: q = 0', 'C1: ΔU = w', 'B1: temperature rises'], sig=2, aq='ΔU')
M('M', 4, 'An ideal gas is heated at constant pressure. Compared with heating the same gas by the same temperature at constant volume, which is correct?', 'More heat is needed at constant pressure, because the gas also does work as it expands', ['Less heat is needed at constant pressure', 'The same heat is needed', 'No heat is needed at constant pressure'], 'ΔU is the same for the same temperature rise. At constant pressure w = −pΔV < 0, so q = ΔU − w is larger.', ['C1: ΔU depends only on T', 'C1: work done at constant p', 'C1: q larger'])
N('M', 3, 'A gas cylinder\'s piston (area 0.015 m²) is pushed in 8.0 cm against a constant gas pressure of 2.4 × 10⁵ Pa, while 120 J escapes by heating. Calculate ΔU.', 2.4e5 * 0.015 * 0.08 - 120, 'J', 'w = pAd = 2.4 × 10⁵ × 0.015 × 0.080 = 288 J. ΔU = q + w = −120 + 288 = 168 J', ['C1: ΔV = Ad', 'C1: w = pΔV positive', 'C1: ΔU'], aq='ΔU')
N('M', 3, 'A p–V graph shows a gas expanding at constant pressure 4.0 × 10⁵ Pa from 1.0 × 10⁻³ m³ to 3.5 × 10⁻³ m³. Calculate the area under the line and state what it represents. Give the area.', 4.0e5 * 2.5e-3, 'J', 'Area = pΔV = 4.0 × 10⁵ × 2.5 × 10⁻³ = 1000 J: the work done by the gas', ['C1: area = pΔV', 'B1: work done by gas'], sig=2, aq='W')
M('M', 3, 'A sealed rigid container of gas is heated. What happens to the work done and the internal energy?', 'No work is done and all the heat increases the internal energy', ['Work is done by the gas and ΔU = 0', 'Work is done on the gas and ΔU = q + w', 'The internal energy falls'], 'Rigid means ΔV = 0, so w = 0 and ΔU = q.', ['C1: ΔV = 0 so w = 0', 'C1: ΔU = q'])
N('M', 4, 'An ideal gas expands isothermally, doing 650 J of work. It is then compressed adiabatically back to its original volume with 820 J of work done on it. Calculate the total change in internal energy over both stages.', 820, 'J', 'Stage 1 (isothermal): ΔU₁ = 0. Stage 2 (adiabatic): q = 0, ΔU₂ = w = +820 J. Total ΔU = 0 + 820 = 820 J', ['C1: isothermal ΔU = 0', 'C1: adiabatic ΔU = w', 'C1: total'], sig=2, aq='ΔU')
M('M', 3, 'A gas cools at constant volume. Which describes q, w and ΔU?', 'q < 0, w = 0, ΔU < 0', ['q > 0, w = 0, ΔU > 0', 'q < 0, w > 0, ΔU = 0', 'q = 0, w < 0, ΔU < 0'], 'Constant volume: w = 0. Cooling: energy leaves, q < 0, so ΔU = q < 0.', ['C1: w = 0', 'C1: q and ΔU negative'])
N('M', 3, 'A gas is heated with 2.0 kJ; its internal energy increases by 1.4 kJ. Calculate the work done by the gas, and state whether it expanded or was compressed. Give the work done by the gas.', 600, 'J', 'w = ΔU − q = 1400 − 2000 = −600 J. The work done BY the gas = q − ΔU = 2000 − 1400 = 600 J: it expanded', ['C1: w = ΔU − q', 'B1: sign interpretation'], sig=2, aq='W')
N('M', 4, 'A cylinder contains gas at 1.0 × 10⁵ Pa. 500 J of heat is supplied and the gas expands at constant pressure, increasing its internal energy by 300 J. Calculate the increase in volume.', (500 - 300) / 1.0e5, 'm³', 'w = ΔU − q = 300 − 500 = −200 J, so the gas did 200 J of work. ΔV = W/p = 200 ÷ 1.0 × 10⁵ = 2.0 × 10⁻³ m³', ['C1: w = ΔU − q', 'C1: W = pΔV', 'C1: rearranged'], sig=2, aq='ΔV')
M('M', 3, 'Why do the gas and nozzle cool when an aerosol can is sprayed?', 'The gas expands quickly, doing work on the surroundings with little heat entering, so its internal energy falls', ['The gas absorbs heat from the nozzle', 'The pressure inside rises', 'The gas condenses'], 'Rapid expansion ≈ adiabatic: q ≈ 0 and w < 0, so ΔU < 0 and the temperature falls.', ['C1: rapid expansion, q ≈ 0', 'C1: w negative so ΔU negative'])
N('M', 3, 'A gas is compressed adiabatically and its internal energy rises by 240 J. It then cools at constant volume, losing 90 J. Calculate the final change in internal energy from the start.', 150, 'J', 'Stage 1: ΔU = +240 J. Stage 2: ΔU = q = −90 J. Total = 240 − 90 = 150 J', ['C1: stage 1', 'C1: stage 2 w = 0'], sig=2, aq='ΔU')
# hard
N('H', 6, 'A gas is taken round a cycle ABCA. A → B: heated at constant volume, 500 J supplied. B → C: expands isothermally, doing 350 J of work. C → A: compressed at constant pressure 1.0 × 10⁵ Pa by 2.0 × 10⁻³ m³. (a) Calculate w for C → A. (b) Use ΔU = 0 for the cycle to find the net heat exchanged. (c) Calculate the heat transferred in C → A, stating its direction. Give only the answer to (c).', -(500 + 200), 'J',
  '(a) w = +pΔV = 1.0 × 10⁵ × 2.0 × 10⁻³ = +200 J (work done on the gas). (b) Net w = 0 − 350 + 200 = −150 J, so net q = +150 J. (c) ΔU: A→B +500 J; B→C 0; C→A must be −500 J to close the cycle, so q = ΔU − w = −500 − 200 = −700 J: 700 J leaves the gas.',
  ['A1: w = +200 J', 'C1: ΔU = 0 for cycle', 'A1: net q', 'C1: ΔU for C → A', 'C1: q = ΔU − w', 'A1: q with direction'], sign=True, aq='q')
N('H', 5, 'An ideal gas at 1.2 × 10⁵ Pa is heated at constant pressure and its volume increases from 3.0 × 10⁻³ m³ to 4.5 × 10⁻³ m³. For this gas, ΔU = 1.5pΔV at constant pressure. (a) Calculate the work done by the gas. (b) Calculate ΔU. (c) Calculate the heat supplied. Give only the answer to (c).', 2.5 * 1.2e5 * 1.5e-3, 'J',
  '(a) W = pΔV = 1.2 × 10⁵ × 1.5 × 10⁻³ = 180 J. (b) ΔU = 1.5 × 180 = 270 J. (c) q = ΔU − w = 270 − (−180) = 450 J',
  ['C1: W = pΔV', 'A1: W', 'A1: ΔU', 'C1: q = ΔU − w', 'A1: q'], aq='q')
N('H', 6, 'In a refrigerator, a refrigerant gas is compressed adiabatically (300 J of work done on it), then loses 820 J by heating in the condenser at roughly constant volume, then expands, absorbing 520 J from the food compartment while doing no external work. (a) Calculate ΔU for each stage. (b) Show that the net ΔU over the cycle is zero. (c) Calculate the net energy transferred to the room by heating per cycle. Give only the answer to (c).', 820, 'J',
  '(a) Compression: ΔU = +300 J. Condenser: ΔU = −820 J. Expansion: ΔU = +520 J. (b) 300 − 820 + 520 = 0. (c) The room receives 520 + 300 = 820 J per cycle (the heat taken from the food plus the work done).',
  ['A1: stage 1', 'A1: stage 2', 'A1: stage 3', 'M1: sum zero', 'B1: 820 J to the room', 'B1: equals heat removed + work'], sig=2, aq='q')
N('H', 5, 'A student compresses air in a bicycle pump: the handle moves 20 cm against an average force of 150 N, so quickly that no heat escapes. (a) Calculate the work done on the air. (b) State ΔU. (c) The air (0.0050 mol) has ΔU = 1.5nRΔT (monatomic model). Calculate the temperature rise. Give only the answer to (c).' + take('R'), 150 * 0.20 / (1.5 * 0.0050 * 8.31), 'K',
  f'(a) w = Fd = 150 × 0.20 = 30 J. (b) q = 0, so ΔU = +30 J. (c) ΔT = ΔU/(1.5nR) = 30 ÷ (1.5 × 0.0050 × 8.31) = {sf(30 / (1.5 * 0.005 * 8.31))} K (real air is diatomic, so the rise is less).',
  ['C1: w = Fd', 'A1: 30 J', 'B1: ΔU = w', 'C1: ΔU = 1.5nRΔT', 'A1: ΔT'], aq='ΔT')
N('H', 6, 'A gas follows a straight-line path on a p–V diagram from (1.0 × 10⁻³ m³, 3.0 × 10⁵ Pa) to (4.0 × 10⁻³ m³, 1.0 × 10⁵ Pa). Its internal energy at the start and end is the same. (a) Calculate the work done by the gas (area of the trapezium). (b) State ΔU. (c) Calculate the heat supplied. Give only the answer to (c).', 0.5 * (3.0e5 + 1.0e5) * 3.0e-3, 'J',
  '(a) Area = ½(3.0 × 10⁵ + 1.0 × 10⁵) × 3.0 × 10⁻³ = 600 J. (b) ΔU = 0. (c) q = ΔU − w = 0 − (−600) = 600 J',
  ['C1: trapezium area', 'A1: 600 J', 'B1: ΔU = 0', 'C1: q = ΔU − w', 'C1: w negative for expansion', 'A1: q'], sig=2, aq='q')

# ═════════════════════════ 19.3 Internal energy (16/17/9) ═════════════════════════
lesson('19.3')
M('E', 1, 'What is the internal energy of a substance?', 'The sum of the random kinetic and potential energies of all its molecules', ['The kinetic energy of the substance as a whole', 'The heat it contains', 'The potential energy due to its height'], 'Internal energy is the total of the randomly distributed microscopic kinetic and potential energies.')
M('E', 1, 'Why is the internal energy of an ideal gas only kinetic energy?', 'There are no forces between the molecules, so they have no potential energy', ['The molecules do not move', 'The molecules are very heavy', 'The gas is always hot'], 'In an ideal gas, intermolecular forces are assumed zero (except in collisions), so Ep = 0.')
M('E', 1, 'A block of ice melts at 0 °C. What happens to its internal energy?', 'It increases, because the molecular potential energy increases', ['It stays the same, because the temperature is constant', 'It decreases', 'It increases because the kinetic energy increases'], 'Energy is supplied to break bonds; the potential energy rises while the kinetic energy (temperature) is unchanged.')
M('E', 1, 'Which change increases the internal energy of a gas?', 'Heating it at constant volume', ['Letting it expand adiabatically', 'Cooling it', 'Letting it do work with no heat supplied'], 'Heating at constant volume: ΔU = q > 0.')
N('E', 2, 'The internal energy of a monatomic ideal gas is U = (3/2)nRT. Calculate U for 1.5 mol at 300 K.' + take('R'), 1.5 * 1.5 * 8.31 * 300, 'J', f'U = 1.5 × 1.5 × 8.31 × 300 = {sf(1.5 * 1.5 * 8.31 * 300)} J', ['C1: U = (3/2)nRT'], aq='U')
N('E', 2, '3.0 mol of helium (monatomic) is heated from 280 K to 330 K. Calculate the increase in its internal energy.' + take('R'), 1.5 * 3.0 * 8.31 * 50, 'J', f'ΔU = (3/2)nRΔT = 1.5 × 3.0 × 8.31 × 50 = {sf(1.5 * 3 * 8.31 * 50)} J', ['C1: ΔU = (3/2)nRΔT'], aq='ΔU')
M('E', 1, 'A ball is thrown so that it moves faster. Does its internal energy change?', 'No: the kinetic energy of the whole ball is not part of its internal energy', ['Yes, it increases', 'Yes, it decreases', 'Only if it spins'], 'Internal energy counts only random molecular motion relative to the centre of mass, not ordered motion of the whole object.')
M('E', 1, 'Two identical blocks are at the same temperature. Block X is 10 m higher than block Y. Which statement is correct?', 'They have the same internal energy', ['X has more internal energy', 'Y has more internal energy', 'X has less internal energy'], 'Gravitational potential energy of the whole block is not internal energy. Same material and temperature means the same internal energy.')
N('E', 2, 'A monatomic gas has internal energy 4500 J at 300 K. What is its internal energy at 400 K?', 4500 * 400 / 300, 'J', 'U ∝ T for an ideal gas: U = 4500 × 400 ÷ 300 = 6000 J', ['C1: U ∝ T'], sig=2, aq='U')
M('E', 1, 'What happens to the internal energy of water as it freezes at 0 °C?', 'It decreases', ['It increases', 'It stays the same', 'It becomes zero'], 'Freezing releases energy as bonds form, so the potential energy (and internal energy) decreases at constant temperature.')
N('E', 2, 'Calculate the mean kinetic energy of the molecules in 2.0 mol of argon at 250 K, given that the total internal energy is (3/2)nRT. Give your answer in units of 10⁻²¹ J.' + take('R', 'NA'), 1.5 * 8.31 * 250 / 6.02e23, '10⁻²¹ J', f'U = 1.5 × 2.0 × 8.31 × 250 = {sf(1.5 * 2 * 8.31 * 250)} J. Mean Ek = U/N = {sf(1.5 * 2 * 8.31 * 250, 4)} ÷ (2.0 × 6.02 × 10²³) = {sf(1.5 * 8.31 * 250 / 6.02e23)} J', ['C1: divide by number of molecules'], aq='Ek')
M('E', 1, 'Which statement about internal energy is correct?', 'It depends only on the state of the system, not on how it got there', ['It depends on the route taken to reach the state', 'It is the same as temperature', 'It is always zero for a solid'], 'Internal energy is a state function: two routes to the same state give the same U.')
N('E', 2, 'The internal energy of a gas increases by 900 J when 1200 J is supplied by heating. How much work was done by the gas?', 300, 'J', 'w = ΔU − q = 900 − 1200 = −300 J. Work done by the gas = q − ΔU = 1200 − 900 = 300 J', ['C1: ΔU = q + w'], sig=2, aq='W')
M('E', 1, 'A copper block is heated from 20 °C to 80 °C. Which energy of its atoms mainly increases?', 'The random kinetic energy of the vibrating atoms (and their potential energy)', ['The kinetic energy of the block as a whole', 'The nuclear energy', 'The gravitational potential energy'], 'Heating a solid makes its atoms vibrate more vigorously: both their random kinetic and potential energies rise.')
N('E', 2, 'An ideal monatomic gas at 200 K has internal energy 2.5 kJ. At what temperature is its internal energy 5.0 kJ?', 400, 'K', 'U ∝ T: T = 200 × 5.0 ÷ 2.5 = 400 K', ['C1: U ∝ T'], sig=2, aq='T')
M('E', 1, 'Why does compressing a gas quickly raise its temperature?', 'Work done on the gas increases its internal energy, and so the molecules\' mean kinetic energy', ['The molecules become heavier', 'The gas absorbs heat from the pump', 'The number of molecules increases'], 'w > 0 with q ≈ 0 gives ΔU > 0; for an ideal gas this means a higher temperature.')
# medium
N('M', 3, 'A sample of 0.50 mol of neon (monatomic) at 300 K is heated at constant volume until its internal energy rises by 1500 J. Calculate its final temperature.' + take('R'), 300 + 1500 / (1.5 * 0.5 * 8.31), 'K', f'ΔT = ΔU/((3/2)nR) = 1500 ÷ (1.5 × 0.50 × 8.31) = {sf(1500 / (0.75 * 8.31))} K. Final T = 300 + {sf(1500 / (0.75 * 8.31), 4)} = {sf(300 + 1500 / (0.75 * 8.31))} K', ['C1: ΔU = (3/2)nRΔT', 'C1: ΔT', 'C1: add'], aq='T')
M('M', 3, 'A liquid is heated at its boiling point. Which row is correct for the molecules?', 'Mean kinetic energy unchanged; potential energy increases', ['Mean kinetic energy increases; potential energy unchanged', 'Both increase', 'Both decrease'], 'At constant temperature the mean Ek is unchanged; energy goes into separating the molecules (Ep rises).', ['C1: constant T', 'C1: potential energy rises'])
N('M', 3, 'A gas absorbs 800 J by heating and its internal energy rises by 500 J. Calculate the work done on the gas and state what this means physically. Give the work done on the gas.', -300, 'J', 'w = ΔU − q = 500 − 800 = −300 J: the gas did 300 J of work on its surroundings (it expanded)', ['C1: w = ΔU − q', 'B1: interpretation'], sig=2, sign=True, aq='w')
N('M', 4, 'Two moles of a monatomic ideal gas are heated from 0 °C to 100 °C. Calculate the increase in internal energy, and the mean increase in kinetic energy per molecule. Give the increase per molecule in units of 10⁻²¹ J.' + take('R', 'NA'), 1.5 * 8.31 * 100 / 6.02e23, '10⁻²¹ J',
  f'ΔU = 1.5nRΔT = 1.5 × 2 × 8.31 × 100 = {sf(1.5 * 2 * 8.31 * 100)} J. Per molecule: {sf(2493, 4)} ÷ (2 × 6.02 × 10²³) = {sf(1.5 * 8.31 * 100 / 6.02e23)} J', ['C1: ΔT = 100 K', 'C1: ΔU', 'C1: ÷ number of molecules'], aq='Δ⟨Ek⟩')
M('M', 3, 'Why does the internal energy of a real gas depend on its volume as well as its temperature, but that of an ideal gas does not?', 'Real gas molecules attract each other, so their potential energy depends on their separation', ['Ideal gases have heavier molecules', 'Real gases have no kinetic energy', 'Ideal gases cannot change volume'], 'Intermolecular forces give real molecules potential energy that varies with spacing; ideal gas molecules have none.', ['C1: intermolecular forces', 'C1: Ep depends on separation'])
N('M', 3, 'A 0.20 kg lead bullet travelling at 300 m s⁻¹ hits a steel plate and stops. Assuming all its kinetic energy becomes internal energy of the bullet, calculate the increase in internal energy.', 0.5 * 0.20 * 300 ** 2, 'J', 'ΔU = ½mv² = 0.5 × 0.20 × 300² = 9000 J', ['C1: Ek = ½mv²', 'B1: becomes internal energy'], sig=2, aq='ΔU')
N('M', 4, 'In the previous situation, lead has c = 130 J kg⁻¹ K⁻¹. If 60 % of the bullet\'s kinetic energy (9000 J) heats the bullet, calculate its temperature rise.', 0.60 * 9000 / (0.20 * 130), 'K', 'Energy to bullet = 0.60 × 9000 = 5400 J. ΔT = E/(mc) = 5400 ÷ (0.20 × 130) = 208 K', ['C1: 60 % of Ek', 'C1: mcΔθ', 'C1: rearranged'], aq='ΔT')
M('M', 3, 'Which process leaves the internal energy of an ideal gas unchanged?', 'An isothermal expansion', ['An adiabatic expansion', 'Heating at constant volume', 'An adiabatic compression'], 'U depends only on T for an ideal gas; isothermal means constant T.', ['C1: U depends only on T', 'C1: isothermal'])
N('M', 3, 'Water falls 50 m over a waterfall. Assuming all the gravitational potential energy becomes internal energy of the water, calculate the rise in temperature.' + take('g') + WATER, 9.81 * 50 / 4200, 'K', 'mgh = mcΔθ, so Δθ = gh/c = 9.81 × 50 ÷ 4200 = 0.117 K', ['C1: mgh = mcΔθ', 'C1: mass cancels'], aq='Δθ')
M('M', 4, 'A gas is taken from state X to state Y by two routes. Route 1: q = 600 J, w = −200 J. Route 2: q = 450 J. What is w for route 2?', '−50 J', ['−200 J', '+50 J', '−650 J'], 'ΔU is the same for both: route 1 gives ΔU = 400 J. Route 2: w = ΔU − q = 400 − 450 = −50 J.', ['C1: ΔU same for both routes', 'C1: ΔU = 400 J', 'C1: w = −50 J'])
N('M', 3, 'A monatomic gas sample has internal energy 3.0 kJ. It does 1.2 kJ of work while 0.8 kJ is supplied by heating. Calculate its new internal energy.', 3000 - 1200 + 800, 'J', 'ΔU = q + w = 800 − 1200 = −400 J. New U = 3000 − 400 = 2600 J', ['C1: ΔU = q + w', 'C1: add to original'], sig=2, aq='U')
M('M', 3, 'A hot metal block at 200 °C is dropped into cold water and both reach 30 °C. Which statement about energy is correct?', 'The internal energy lost by the block equals the internal energy gained by the water (if none is lost)', ['The block loses temperature and the water gains temperature in equal amounts', 'The block\'s internal energy stays the same', 'Energy is destroyed as the block cools'], 'Energy is conserved: heat flows from block to water until they are at the same temperature.', ['C1: energy conserved', 'C1: transfer until equal temperature'])
N('M', 4, 'A car of mass 1200 kg brakes from 25 m s⁻¹ to rest. The brake discs (total mass 12 kg, c = 450 J kg⁻¹ K⁻¹) absorb 80 % of the kinetic energy. Calculate the rise in temperature of the discs.', 0.80 * 0.5 * 1200 * 25 ** 2 / (12 * 450), 'K', f'Ek = ½ × 1200 × 25² = {sf(0.5 * 1200 * 625)} J. To discs: 0.80 × {sf(375000, 4)} = {sf(300000, 4)} J. ΔT = 300000 ÷ (12 × 450) = {sf(300000 / 5400)} K', ['C1: Ek', 'C1: 80 %', 'C1: ΔT = E/mc'], aq='ΔT')
N('M', 3, 'At what temperature would a monatomic ideal gas of 0.10 mol have internal energy 500 J?' + take('R'), 500 / (1.5 * 0.10 * 8.31), 'K', f'T = U/((3/2)nR) = 500 ÷ (1.5 × 0.10 × 8.31) = {sf(500 / 1.2465)} K', ['C1: U = (3/2)nRT', 'C1: rearranged'], aq='T')
M('M', 3, 'A sealed bag of air is carried up a mountain at constant temperature and its volume increases. Assuming ideal behaviour, what happens to its internal energy?', 'It stays the same', ['It increases because the volume increases', 'It decreases because the pressure decreases', 'It becomes zero'], 'Ideal gas: U depends only on T. Constant T means constant U.', ['C1: U = f(T) only', 'C1: T constant'])
N('M', 4, 'A 2.0 kg aluminium block (c = 900 J kg⁻¹ K⁻¹) at 20 °C is hammered 100 times; each blow does 15 J of work on it. Half of the energy goes into the block. Calculate its temperature rise.', 0.5 * 100 * 15 / (2.0 * 900), 'K', 'Energy to block = 0.5 × 100 × 15 = 750 J. ΔT = 750 ÷ (2.0 × 900) = 0.417 K', ['C1: total work', 'C1: half to block', 'C1: ΔT = E/mc'], aq='ΔT')
# hard
N('H', 6, 'A cylinder of 0.040 mol of helium (monatomic) at 300 K and 1.0 × 10⁵ Pa is heated at constant pressure to 450 K. (a) Calculate the increase in internal energy. (b) Calculate the work done by the gas, using pΔV = nRΔT. (c) Calculate the heat supplied. Give only the answer to (c).' + take('R'), 2.5 * 0.040 * 8.31 * 150, 'J',
  f'(a) ΔU = 1.5nRΔT = 1.5 × 0.040 × 8.31 × 150 = {sf(1.5 * 0.04 * 8.31 * 150)} J. (b) W = nRΔT = 0.040 × 8.31 × 150 = {sf(0.04 * 8.31 * 150)} J. (c) q = ΔU + W = {sf(1.5 * 0.04 * 8.31 * 150, 4)} + {sf(0.04 * 8.31 * 150, 4)} = {sf(2.5 * 0.04 * 8.31 * 150)} J',
  ['C1: ΔU = 1.5nRΔT', 'A1: ΔU', 'C1: W = nRΔT', 'A1: W', 'C1: q = ΔU − w', 'A1: q'], aq='q')
N('H', 5, 'A lead shot of mass 0.50 kg falls 1.2 m inside a closed tube; the tube is inverted 50 times so the shot falls 50 times. Lead has c = 130 J kg⁻¹ K⁻¹. (a) Calculate the total loss of gravitational potential energy. (b) State where it goes. (c) Calculate the temperature rise of the lead, assuming no losses. Give only the answer to (c).' + take('g'), 50 * 9.81 * 1.2 / 130, 'K',
  f'(a) 50 × 0.50 × 9.81 × 1.2 = {sf(50 * 0.5 * 9.81 * 1.2)} J. (b) Into internal energy of the lead (and a little to the tube and air). (c) ΔT = E/(mc) = {sf(50 * 0.5 * 9.81 * 1.2, 4)} ÷ (0.50 × 130) = {sf(50 * 9.81 * 1.2 / 130)} K',
  ['C1: 50mgh', 'A1: Ep', 'B1: internal energy', 'C1: ΔT = E/mc', 'A1: ΔT'], aq='ΔT')
N('H', 6, 'When 1.0 kg of water boils at 100 °C and atmospheric pressure (1.01 × 10⁵ Pa) its volume increases from 1.0 × 10⁻³ m³ to 1.67 m³. L_v = 2.26 × 10⁶ J kg⁻¹. (a) Calculate the work done pushing back the atmosphere. (b) Calculate the increase in internal energy. (c) Calculate the percentage of the latent heat that increases the internal energy. Give only the answer to (c).', (2.26e6 - 1.01e5 * (1.67 - 0.001)) / 2.26e6 * 100, '%',
  f'(a) W = pΔV = 1.01 × 10⁵ × (1.67 − 0.001) = {sf(1.01e5 * 1.669)} J. (b) ΔU = q − W = 2.26 × 10⁶ − {sf(1.01e5 * 1.669, 4)} = {sf(2.26e6 - 1.01e5 * 1.669)} J. (c) {sf(2.26e6 - 1.01e5 * 1.669, 4)} ÷ 2.26 × 10⁶ × 100 = {sf((2.26e6 - 1.01e5 * 1.669) / 2.26e6 * 100)} %',
  ['C1: W = pΔV', 'A1: W', 'C1: ΔU = q + w with w negative', 'A1: ΔU', 'A1: percentage', 'B1: most energy separates molecules'], aq='percentage')
N('H', 5, 'A monatomic ideal gas (n = 0.25 mol) is compressed adiabatically and its temperature rises from 290 K to 410 K. (a) Calculate ΔU. (b) Calculate the work done on the gas. (c) Explain why the temperature rise would be smaller if the compression were slow. Give only the answer to (b).' + take('R'), 1.5 * 0.25 * 8.31 * 120, 'J',
  f'(a) ΔU = 1.5nRΔT = 1.5 × 0.25 × 8.31 × 120 = {sf(1.5 * 0.25 * 8.31 * 120)} J. (b) q = 0, so w = ΔU = {sf(1.5 * 0.25 * 8.31 * 120)} J. (c) A slow compression gives time for heat to flow out to the surroundings (q < 0), so ΔU and ΔT are smaller.',
  ['C1: ΔU formula', 'A1: ΔU', 'B1: q = 0', 'A1: w', 'B1: heat escapes'], aq='w')

# ── extras 19.1–19.3 ──
lesson('19.1')
N('M', 3, 'A 0.25 kg aluminium pan (c = 900 J kg⁻¹ K⁻¹) containing 0.50 kg of water at 100 °C is on a 1.8 kW hob. Ignoring losses, how long does it take to boil away 0.10 kg of the water?' + VAPOUR, 0.10 * LV / 1800, 's', f'Pan and water are already at 100 °C, so all the energy boils water: E = mL_v = 0.10 × 2.26 × 10⁶ = {sf(0.1 * LV)} J, t = E/P = {sf(0.1 * LV)} ÷ 1800 = {sf(0.1 * LV / 1800)} s', ['B1: pan needs no heating', 'C1: E = mL_v', 'C1: t = E/P'], aq='t')
N('H', 5, 'A 0.040 kg ice cube at 0 °C is placed in 0.20 kg of water at 30 °C in an insulated cup. (a) Calculate the energy needed to melt the ice. (b) Show that all the ice melts. (c) Calculate the final temperature. Give only the answer to (c).' + WATER + FUSION, (0.20 * CW * 30 - 0.04 * LF) / (0.24 * CW), '°C',
  f'(a) 0.040 × 3.34 × 10⁵ = {sf(0.04 * LF)} J. (b) The water can give 0.20 × 4200 × 30 = {sf(0.2 * 4200 * 30)} J cooling to 0 °C — more than needed. (c) 0.20 × 4200 × (30 − θ) = {sf(0.04 * LF, 4)} + 0.040 × 4200 × θ: θ = (25200 − {sf(0.04 * LF, 4)}) ÷ 1008 = {sf((0.2 * CW * 30 - 0.04 * LF) / (0.24 * CW))} °C',
  ['A1: energy to melt', 'B1: comparison', 'M1: energy balance', 'C1: includes warming of melted ice', 'A1: θ'], aq='θ')
N('H', 6, 'An ice rink is cooled by pipes carrying cold brine. A 5.0 cm layer of water at 0 °C over a 30 m × 60 m rink (water density 1000 kg m⁻³) must be frozen. (a) Calculate the mass of water. (b) Calculate the energy to be removed. (c) The refrigeration plant removes energy at 250 kW. Calculate the time taken, in hours. Give only the answer to (c).' + FUSION, 1000 * 30 * 60 * 0.05 * LF / 250e3 / 3600, 'h',
  f'(a) V = 30 × 60 × 0.050 = 90 m³, m = 9.0 × 10⁴ kg. (b) E = mL = 9.0 × 10⁴ × 3.34 × 10⁵ = {sf(9e4 * LF)} J. (c) t = E/P = {sf(9e4 * LF, 4)} ÷ 2.5 × 10⁵ = {sf(9e4 * LF / 2.5e5)} s. In hours: {sf(9e4 * LF / 2.5e5, 4)} ÷ 3600 = {sf(9e4 * LF / 2.5e5 / 3600)}',
  ['C1: volume', 'A1: mass', 'C1: E = mL', 'A1: E', 'C1: t = E/P', 'A1: t in hours'], aq='t')
N('H', 5, 'A student finds the specific latent heat of vaporisation by boiling water with a 1.0 kW kettle on a balance. The mass falls from 1.234 kg to 1.138 kg in 4.0 minutes once boiling. (a) Calculate the mass boiled away. (b) Calculate L_v. (c) Explain why the result is too high and suggest an improvement. Give only the answer to (b).', 1000 * 240 / 0.096, 'J kg⁻¹',
  f'(a) 1.234 − 1.138 = 0.096 kg. (b) L_v = Pt/m = 1000 × 240 ÷ 0.096 = {sf(240000 / 0.096)} J kg⁻¹. (c) Some energy is lost to the surroundings, so less water boils than the energy suggests; insulate the kettle, or use two powers to eliminate the losses.',
  ['A1: mass', 'C1: E = Pt', 'A1: L_v', 'B1: losses make L too large', 'B1: improvement'], aq='L_v')
N('H', 5, 'Molten aluminium at its melting point (660 °C) is poured into a mould and solidifies, then cools to 20 °C. Mass 2.0 kg, L_f = 3.97 × 10⁵ J kg⁻¹, c = 900 J kg⁻¹ K⁻¹. (a) Calculate the energy released on solidifying. (b) Calculate the energy released on cooling. (c) Calculate the total. Give only the answer to (c).', 2.0 * 3.97e5 + 2.0 * 900 * 640, 'J',
  f'(a) 2.0 × 3.97 × 10⁵ = {sf(7.94e5)} J. (b) 2.0 × 900 × 640 = {sf(2 * 900 * 640)} J. (c) {sf(7.94e5, 4)} + {sf(2 * 900 * 640, 4)} = {sf(2 * 3.97e5 + 2 * 900 * 640)} J',
  ['C1: mL', 'A1: (a)', 'C1: mcΔθ with Δθ = 640 K', 'A1: (b)', 'A1: total'], aq='E')
N('H', 6, 'A heater supplies energy at a constant rate to 0.30 kg of a substance that starts as a solid. Its temperature rises from 20 °C to 80 °C in 120 s, stays at 80 °C for 300 s, then rises again. The specific heat capacity of the solid is 1500 J kg⁻¹ K⁻¹. (a) Calculate the power of the heater. (b) Calculate the specific latent heat of fusion. (c) State one assumption made. Give only the answer to (b).', (0.30 * 1500 * 60 / 120) * 300 / 0.30, 'J kg⁻¹',
  f'(a) P = mcΔθ/t = 0.30 × 1500 × 60 ÷ 120 = {sf(0.3 * 1500 * 60 / 120)} W. (b) L = Pt/m = {sf(225)} × 300 ÷ 0.30 = {sf(225 * 300 / 0.3)} J kg⁻¹. (c) No energy is lost to the surroundings (or the heater power is constant).',
  ['C1: energy for temperature rise', 'A1: P', 'C1: E = Pt for plateau', 'C1: L = E/m', 'A1: L', 'B1: assumption'], aq='L')
N('H', 5, 'A person loses 2.4 × 10⁶ J kg⁻¹ of energy for each kg of sweat evaporated. During a run she produces 900 W of heat, and 70 % must be removed by sweating. (a) Calculate the cooling power from sweating. (b) Calculate the mass of sweat evaporated in 1.0 hour. (c) Explain why sweating is less effective in humid air. Give only the answer to (b).', 0.70 * 900 * 3600 / 2.4e6, 'kg',
  f'(a) 0.70 × 900 = 630 W. (b) m = Pt/L = 630 × 3600 ÷ 2.4 × 10⁶ = {sf(630 * 3600 / 2.4e6)} kg. (c) In humid air fewer water molecules escape from the skin (more return), so the net rate of evaporation — and cooling — is lower.',
  ['A1: 630 W', 'C1: E = Pt', 'C1: m = E/L', 'A1: m', 'B1: humid air reduces net evaporation'], aq='m')

lesson('19.2')
N('M', 3, 'A gas in a syringe is pushed in: 25 J of work is done on it while it loses 10 J by heating. Calculate ΔU.', 15, 'J', 'ΔU = q + w = −10 + 25 = 15 J', ['C1: q negative', 'C1: w positive'], sig=2, aq='ΔU')
N('M', 4, 'A gas does 1.5 kJ of work as it expands from 2.0 × 10⁻³ m³ at a constant pressure. Its volume becomes 9.5 × 10⁻³ m³. Calculate the pressure.', 1500 / 7.5e-3, 'Pa', 'ΔV = 9.5 × 10⁻³ − 2.0 × 10⁻³ = 7.5 × 10⁻³ m³. W = pΔV, so p = W/ΔV = 1500 ÷ 7.5 × 10⁻³ = 2.0 × 10⁵ Pa', ['C1: ΔV', 'C1: W = pΔV', 'C1: rearranged'], sig=2, aq='p')
N('H', 5, 'A gas is heated at constant volume from A to B, receiving 300 J, then expands at constant pressure 2.0 × 10⁵ Pa from 1.0 × 10⁻³ m³ to 2.5 × 10⁻³ m³ (B to C), receiving 750 J. (a) Calculate ΔU for A to B. (b) Calculate the work done by the gas for B to C. (c) Calculate ΔU for B to C and the total ΔU from A to C. Give only the total in (c).', 300 + 750 - 2.0e5 * 1.5e-3, 'J',
  '(a) w = 0, so ΔU = 300 J. (b) W = pΔV = 2.0 × 10⁵ × 1.5 × 10⁻³ = 300 J. (c) ΔU(BC) = 750 − 300 = 450 J. Total = 300 + 450 = 750 J',
  ['B1: w = 0 at constant volume', 'A1: ΔU(AB)', 'C1: W = pΔV', 'C1: ΔU(BC) = q + w', 'A1: total'], aq='ΔU')
N('H', 6, 'A heat engine takes in 2400 J per cycle from a hot source and does 600 J of work, returning to its starting state. (a) State ΔU for the cycle. (b) Calculate the heat rejected to the cold sink per cycle. (c) Calculate the efficiency, and the rate of heat rejection at 50 cycles per second. Give only the rate in (c).', (2400 - 600) * 50, 'W',
  '(a) ΔU = 0 for a complete cycle. (b) q_in − q_out = W, so q_out = 2400 − 600 = 1800 J. (c) Efficiency = 600 ÷ 2400 × 100 = 25 %. Rate = 1800 × 50 = 90000 W',
  ['B1: ΔU = 0', 'C1: energy balance', 'A1: 1800 J', 'A1: 25 %', 'C1: × 50', 'A1: rate'], aq='P')
N('H', 5, 'A gas expands from 1.0 × 10⁻³ m³ to 3.0 × 10⁻³ m³. On a p–V graph its pressure falls linearly from 5.0 × 10⁵ Pa to 2.0 × 10⁵ Pa. 1200 J is supplied by heating. (a) Calculate the work done by the gas from the area under the graph. (b) Calculate ΔU. (c) State whether the temperature rose or fell, assuming ideal behaviour. Give only the answer to (b).', 1200 - 0.5 * (5.0e5 + 2.0e5) * 2.0e-3, 'J',
  '(a) W = ½(5.0 × 10⁵ + 2.0 × 10⁵) × 2.0 × 10⁻³ = 700 J. (b) ΔU = q + w = 1200 − 700 = 500 J. (c) ΔU > 0, so the temperature rose.',
  ['C1: trapezium area', 'A1: 700 J', 'C1: w = −700 J', 'A1: ΔU', 'B1: temperature rose'], sig=2, aq='ΔU')

lesson('19.3')
N('M', 3, 'A sample of 0.60 mol of argon (monatomic) loses 450 J of internal energy. Calculate its fall in temperature.' + take('R'), 450 / (1.5 * 0.60 * 8.31), 'K', f'ΔT = ΔU/((3/2)nR) = 450 ÷ (1.5 × 0.60 × 8.31) = {sf(450 / (0.9 * 8.31))} K', ['C1: ΔU = (3/2)nRΔT', 'C1: rearranged'], aq='ΔT')
N('H', 5, 'A meteorite of mass 2.0 kg enters the atmosphere at 15 km s⁻¹ and is slowed to 200 m s⁻¹. (a) Calculate its loss of kinetic energy. (b) Suggest where the energy goes. (c) If 1 % of it raised the meteorite\'s temperature (c = 700 J kg⁻¹ K⁻¹), calculate the temperature rise, and comment. Give only the answer to (c).', 0.01 * 0.5 * 2.0 * (15000 ** 2 - 200 ** 2) / (2.0 * 700), 'K',
  f'(a) ΔEk = ½ × 2.0 × (15000² − 200²) = {sf(0.5 * 2 * (15000 ** 2 - 200 ** 2))} J. (b) Internal energy of the air and meteorite, light and sound. (c) ΔT = 0.01 × {sf(0.5 * 2 * (15000 ** 2 - 200 ** 2), 4)} ÷ (2.0 × 700) = {sf(0.01 * (15000 ** 2 - 200 ** 2) / 1400)} K — far above melting, so the surface vaporises (ablates).',
  ['C1: ΔEk', 'A1: ΔEk', 'B1: internal energy of air/meteorite', 'C1: ΔT = E/mc', 'A1: ΔT and comment'], aq='ΔT')
N('H', 6, 'An ideal monatomic gas (n = 0.10 mol) is taken from 300 K to 500 K by two routes. Route P: constant volume then nothing else. Route Q: constant pressure. (a) Calculate ΔU for each route. (b) For route Q, calculate the work done by the gas (pΔV = nRΔT). (c) Calculate the heat supplied in each route. Give only the heat for route Q in (c).' + take('R'), 2.5 * 0.10 * 8.31 * 200, 'J',
  f'(a) ΔU = 1.5nRΔT = 1.5 × 0.10 × 8.31 × 200 = {sf(1.5 * 0.1 * 8.31 * 200)} J for both (state function). (b) W = nRΔT = 0.10 × 8.31 × 200 = {sf(0.1 * 8.31 * 200)} J. (c) P: q = ΔU = {sf(1.5 * 0.1 * 8.31 * 200)} J. Q: q = ΔU + W = {sf(1.5 * 0.1 * 8.31 * 200, 4)} + {sf(0.1 * 8.31 * 200, 4)} = {sf(2.5 * 0.1 * 8.31 * 200)} J',
  ['A1: ΔU same for both', 'B1: state function', 'A1: W', 'A1: q for P', 'C1: q = ΔU + W', 'A1: q for Q'], aq='q')
N('H', 5, 'A copper rod (mass 0.40 kg, c = 385 J kg⁻¹ K⁻¹) is rubbed with a cloth. The cloth is pushed back and forth through 0.20 m against a friction force of 30 N, 200 times. (a) Calculate the work done against friction. (b) Half of this energy enters the rod. Calculate its temperature rise. (c) Explain why the rod\'s internal energy increases even though no heating by a hotter object occurs. Give only the answer to (b).', 0.5 * 200 * 30 * 0.20 / (0.40 * 385), 'K',
  f'(a) W = 200 × 30 × 0.20 = 1200 J. (b) ΔT = 0.5 × 1200 ÷ (0.40 × 385) = {sf(600 / 154)} K. (c) Work done (not heat) transfers energy to the random motion of the rod\'s atoms: internal energy can rise by work as well as by heating.',
  ['C1: W = Fd × number', 'A1: W', 'C1: ΔT = E/mc', 'A1: ΔT', 'B1: work raises internal energy'], aq='ΔT')
N('H', 6, 'The internal energy of a real gas is U = (3/2)nRT − a(n²/V) for a constant a = 0.14 J m³ mol⁻². 1.0 mol of the gas expands at constant temperature (300 K) from 1.0 × 10⁻³ m³ to 2.0 × 10⁻³ m³. (a) Explain why the second term is negative. (b) Calculate ΔU. (c) Explain why ΔU would be zero for an ideal gas. Give only the answer to (b).', 0.14 * (1 / 1.0e-3 - 1 / 2.0e-3), 'J',
  f'(a) The molecules attract, so their potential energy is negative, and more negative when they are closer (smaller V). (b) ΔU = a n²(1/V₁ − 1/V₂) = 0.14 × (1 ÷ 1.0 × 10⁻³ − 1 ÷ 2.0 × 10⁻³) = {sf(0.14 * 500)} J. (c) An ideal gas has no intermolecular forces, so U depends only on T.',
  ['B1: attraction gives negative Ep', 'B1: more negative when closer', 'C1: ΔU from the a term', 'A1: ΔU', 'B1: ideal gas U = f(T)', 'B1: no Ep'], sig=2, aq='ΔU')

# ═════════════════════════ 19.4 Thermal equilibrium (14/17/11) ═════════════════════════
lesson('19.4')
M('E', 1, 'Two objects are in thermal contact and there is no net flow of energy between them. What can you conclude?', 'They are at the same temperature', ['They have the same internal energy', 'They have the same mass', 'They are made of the same material'], 'Thermal equilibrium means equal temperatures, not equal internal energies.')
M('E', 1, 'In which direction does energy flow by heating between two bodies in contact?', 'From the hotter body to the colder body', ['From the body with more internal energy to the body with less', 'From the larger body to the smaller body', 'In both directions equally, always'], 'Net heat flow is always from higher to lower temperature, whatever the internal energies.')
M('E', 1, 'A thermometer placed in a cup of tea reads a steady value after a minute. Why?', 'It has reached thermal equilibrium with the tea', ['It has run out of mercury', 'The tea has stopped losing energy', 'The thermometer has reached its maximum'], 'The thermometer reads its own temperature, which equals the tea\'s only once they are in thermal equilibrium.')
N('E', 1, 'A cup of coffee at 352 K is placed in a room at 293 K. Calculate the temperature difference.', 59, 'K', 'ΔT = 352 − 293 = 59 K', [], sig=2, aq='ΔT')
M('E', 1, 'A large iceberg at −2 °C and a hot cup of tea at 90 °C. Which statement is correct?', 'The iceberg can have more internal energy but the tea is at the higher temperature', ['The tea must have more internal energy', 'They have the same internal energy', 'The iceberg is hotter'], 'Internal energy depends on mass and material too; temperature decides the direction of heat flow.')
M('E', 1, 'Object A is in thermal equilibrium with B, and B with C. Which is correct?', 'A and C are in thermal equilibrium', ['A is hotter than C', 'C is hotter than A', 'Nothing can be concluded about A and C'], 'This is the zeroth law of thermodynamics: it is why thermometers work.')
N('E', 2, 'A 0.50 kg metal block cools from 80 °C to 30 °C in water, giving 11 250 J to the water. Calculate the specific heat capacity of the metal.', 11250 / (0.50 * 50), 'J kg⁻¹ K⁻¹', 'c = E/(mΔθ) = 11250 ÷ (0.50 × 50) = 450 J kg⁻¹ K⁻¹', ['C1: c = E/mΔθ'], sig=2, aq='c')
M('E', 1, 'Two blocks, one of copper and one of wood, are in a room overnight. The copper feels colder to touch. Which is correct?', 'Both are at the same temperature; copper conducts heat from the hand faster', ['The copper is at a lower temperature', 'The wood is at a higher temperature', 'Copper has no internal energy'], 'In equilibrium both are at room temperature; copper\'s higher conductivity draws heat from the hand faster.')
M('E', 1, 'In an insulated container, a hot block loses 2400 J to some cold water. How much energy does the water gain?', '2400 J', ['1200 J', 'Less than 2400 J, because temperature is lost', '4800 J'], 'In an isolated system energy is conserved: the energy lost by the block equals the energy gained by the water.')
M('E', 1, 'Which quantity is the same for two objects in thermal equilibrium?', 'Temperature', ['Internal energy', 'Specific heat capacity', 'Mass'], 'Thermal equilibrium means no net heat flow, which happens only at equal temperatures.')
N('E', 2, '0.20 kg of water at 60 °C is mixed with 0.20 kg of water at 20 °C. Calculate the final temperature, assuming no losses.', 40, '°C', 'Equal masses of the same substance: θ = (60 + 20) ÷ 2 = 40 °C', ['C1: mean of temperatures for equal masses'], sig=2, aq='θ')
M('E', 1, 'Why does a cold drink in a warm room gradually warm up and stop at room temperature?', 'Energy flows into the drink until it reaches thermal equilibrium with the room', ['The drink makes its own heat', 'The room cools to the drink\'s temperature', 'The drink\'s internal energy is constant'], 'Net heat flows into the drink while it is colder; at equal temperatures the flow stops.')
N('E', 2, 'A 0.10 kg copper block (c = 385 J kg⁻¹ K⁻¹) cools from 95 °C to 25 °C. Calculate the energy it gives out.', 0.10 * 385 * 70, 'J', 'E = mcΔθ = 0.10 × 385 × 70 = 2695 J', ['C1: E = mcΔθ'], aq='E')
M('E', 1, 'Which is the best definition of temperature (in the kinetic model)?', 'A measure of the average random kinetic energy of the particles', ['The total energy of the particles', 'The amount of heat in a body', 'The potential energy of the particles'], 'For an ideal gas the mean translational kinetic energy is (3/2)kT: temperature measures it.')
# medium
N('M', 3, 'A 0.40 kg iron block (c = 450 J kg⁻¹ K⁻¹) at 100 °C is placed in 0.60 kg of water at 18 °C in an insulated container. Calculate the final temperature.' + WATER, (0.40 * 450 * 100 + 0.60 * CW * 18) / (0.40 * 450 + 0.60 * CW), '°C',
  f'Heat lost by iron = heat gained by water: 0.40 × 450 × (100 − θ) = 0.60 × 4200 × (θ − 18). 18000 − 180θ = 2520θ − 45360, θ = 63360 ÷ 2700 = {sf(63360 / 2700)} °C',
  ['M1: heat lost = heat gained', 'C1: substitution', 'C1: solve'], aq='θ')
N('M', 4, 'A 0.25 kg aluminium block at 150 °C is dropped into 0.50 kg of water at 20 °C. The final temperature is 32 °C. Calculate the specific heat capacity of aluminium.' + WATER, 0.50 * CW * 12 / (0.25 * 118), 'J kg⁻¹ K⁻¹',
  f'Heat gained by water = 0.50 × 4200 × 12 = 25200 J. Heat lost by Al = 0.25 × c × 118. c = 25200 ÷ (0.25 × 118) = {sf(25200 / 29.5)} J kg⁻¹ K⁻¹',
  ['C1: heat gained by water', 'C1: equated to heat lost', 'C1: rearranged'], aq='c')
M('M', 3, 'In a method-of-mixtures experiment the final temperature is lower than predicted. Which is the most likely reason?', 'Heat was lost to the container and surroundings', ['The thermometer was too accurate', 'Too much stirring was done', 'The masses were measured in kg'], 'Losses to the surroundings mean less energy stays in the mixture, so it ends cooler.', ['C1: energy lost', 'C1: lower final temperature'])
N('M', 3, 'A 50 g ball bearing (c = 460 J kg⁻¹ K⁻¹) at 300 °C is dropped into 0.20 kg of oil (c = 2000 J kg⁻¹ K⁻¹) at 20 °C. Calculate the final temperature.', (0.05 * 460 * 300 + 0.2 * 2000 * 20) / (0.05 * 460 + 0.2 * 2000), '°C',
  f'0.050 × 460 × (300 − θ) = 0.20 × 2000 × (θ − 20). 6900 − 23θ = 400θ − 8000, θ = 14900 ÷ 423 = {sf(14900 / 423)} °C', ['M1: heat balance', 'C1: substitution', 'C1: solve'], aq='θ')
M('M', 3, 'Two equal masses, one of water and one of copper, start at 80 °C and cool in the same room. Which statement is correct?', 'The copper cools faster, because it has a smaller specific heat capacity', ['The water cools faster', 'They cool at the same rate because they have the same mass', 'The copper ends at a lower final temperature'], 'For the same energy loss per second, the smaller heat capacity (mc) gives a faster temperature fall. Both end at room temperature.', ['C1: smaller c', 'C1: larger temperature change per joule'])
N('M', 4, 'A thermometer of heat capacity 12 J K⁻¹ at 20 °C is placed in 0.030 kg of water at 60 °C. Calculate the temperature it reads, ignoring other losses.' + WATER, (12 * 20 + 0.030 * CW * 60) / (12 + 0.030 * CW), '°C',
  f'12 × (θ − 20) = 0.030 × 4200 × (60 − θ). 12θ − 240 = 7560 − 126θ, θ = 7800 ÷ 138 = {sf(7800 / 138)} °C — the thermometer lowers the water temperature it measures.',
  ['M1: heat balance with heat capacity', 'C1: substitution', 'C1: solve'], aq='θ')
N('M', 3, 'Hot water at 70 °C is added to 2.0 kg of cold water at 15 °C to make a bath at 40 °C. Calculate the mass of hot water needed, ignoring losses.', 2.0 * 25 / 30, 'kg', 'm × (70 − 40) = 2.0 × (40 − 15), so m = 2.0 × 25 ÷ 30 = 1.67 kg', ['C1: heat lost = heat gained', 'C1: c cancels', 'C1: solve'], aq='m')
M('M', 3, 'A hot pan is plunged into a sink of cold water. After a while both are at 35 °C. Which statement is correct?', 'The pan and water are in thermal equilibrium; the water\'s temperature rise was smaller because its heat capacity is larger', ['The pan still has more heat than the water', 'Heat now flows from water to pan', 'The pan is hotter because metal holds heat'], 'Equal temperatures mean equilibrium; the larger heat capacity of the water meant it warmed only a little.', ['C1: equilibrium', 'C1: heat capacity explains different changes'])
N('M', 4, 'A 2.0 kW immersion heater is placed in 4.0 kg of water at 15 °C. Half the heater\'s energy is lost to the surroundings. Calculate the time to reach 45 °C.' + WATER, 4.0 * CW * 30 / (0.5 * 2000), 's', 'Useful power = 0.5 × 2000 = 1000 W. E = mcΔθ = 4.0 × 4200 × 30 = 504000 J. t = 504000 ÷ 1000 = 504 s', ['C1: useful power', 'C1: E = mcΔθ', 'C1: t = E/P'], aq='t')
M('M', 4, 'A copper calorimeter is used in a mixtures experiment but its heat capacity is ignored in the calculation. The calorimeter starts at the same temperature as the cold water. What effect does this have on the calculated specific heat capacity of a hot metal sample?', 'It makes the calculated value too small', ['It makes it too large', 'It has no effect', 'It makes it negative'], 'The calorimeter also absorbs heat from the sample, which is not counted, so the energy lost by the sample is underestimated: c is too small.', ['C1: calorimeter absorbs heat', 'C1: energy gained underestimated', 'C1: c too small'])
N('M', 3, 'A 0.30 kg lump of lead (c = 130 J kg⁻¹ K⁻¹) at 90 °C is dropped into 0.10 kg of water at 20 °C. Calculate the final temperature.' + WATER, (0.3 * 130 * 90 + 0.1 * CW * 20) / (0.3 * 130 + 0.1 * CW), '°C',
  f'0.30 × 130 × (90 − θ) = 0.10 × 4200 × (θ − 20). 3510 − 39θ = 420θ − 8400, θ = 11910 ÷ 459 = {sf(11910 / 459)} °C', ['M1: heat balance', 'C1: substitution', 'C1: solve'], aq='θ')
M('M', 3, 'A large bath and a small cup both contain water at 40 °C. They are each placed in a room at 20 °C. Which reaches room temperature first?', 'The cup, because it has a much smaller heat capacity', ['The bath, because it has a larger surface', 'Both at the same time', 'Neither, because they are at the same temperature'], 'Rate of cooling depends on surface area, but the bath\'s far larger heat capacity means it takes far longer.', ['C1: heat capacity', 'C1: cup cools faster'])
N('M', 4, 'A 0.080 kg brass weight (c = 380 J kg⁻¹ K⁻¹) at 100 °C is put into 0.15 kg of water at 20 °C in a 0.10 kg copper can (c = 390 J kg⁻¹ K⁻¹) also at 20 °C. Calculate the final temperature.' + WATER, (0.08 * 380 * 100 + (0.15 * CW + 0.1 * 390) * 20) / (0.08 * 380 + 0.15 * CW + 0.1 * 390), '°C',
  f'Heat lost by brass = heat gained by water and can: 0.080 × 380 × (100 − θ) = (0.15 × 4200 + 0.10 × 390)(θ − 20). 3040 − 30.4θ = 669θ − 13380, θ = 16420 ÷ 699.4 = {sf(16420 / 699.4)} °C',
  ['M1: include the can', 'C1: substitution', 'C1: solve'], aq='θ')
N('M', 3, 'The temperature of a 1.5 kg concrete block (c = 880 J kg⁻¹ K⁻¹) in a sunny window rises from 18 °C to 31 °C. Calculate the energy it absorbed.', 1.5 * 880 * 13, 'J', 'E = mcΔθ = 1.5 × 880 × 13 = 17160 J', ['C1: E = mcΔθ', 'C1: Δθ = 13 K'], aq='E')
M('M', 3, 'Why can a thermometer only measure the temperature of an object once thermal equilibrium is reached?', 'Before then, heat is still flowing and the thermometer is not at the object\'s temperature', ['The thermometer needs time to warm its batteries', 'Temperature cannot change', 'The object must cool to room temperature first'], 'A thermometer reads its own temperature; it equals the object\'s temperature only when there is no net heat flow.', ['C1: thermometer reads its own temperature', 'C1: equal at equilibrium'])
N('M', 4, 'A 25 W lamp is immersed in 0.50 kg of water. 80 % of its electrical power heats the water. Calculate the temperature rise in 10 minutes.' + WATER, 0.80 * 25 * 600 / (0.5 * CW), 'K', 'E = 0.80 × 25 × 600 = 12000 J. Δθ = E/(mc) = 12000 ÷ (0.50 × 4200) = 5.71 K', ['C1: useful energy', 'C1: t in s', 'C1: Δθ = E/mc'], aq='Δθ')
# hard
N('H', 5, 'A 0.20 kg copper block (c = 385 J kg⁻¹ K⁻¹) is heated in a flame and then dropped into 0.25 kg of water at 16 °C in an insulated cup. The water rises to 38 °C. (a) Calculate the energy gained by the water. (b) Calculate the temperature of the flame, assuming the block reached it. (c) Suggest why this estimate is too low. Give only the answer to (b).' + WATER, 38 + 0.25 * CW * 22 / (0.2 * 385), '°C',
  f'(a) E = 0.25 × 4200 × 22 = 23100 J. (b) 0.20 × 385 × (θ − 38) = 23100, θ = 38 + 23100 ÷ 77 = {sf(38 + 23100 / 77)} °C. (c) The block cools a little while being moved, and some heat escapes, so the estimate is low.',
  ['C1: mcΔθ for water', 'A1: E', 'M1: heat balance', 'A1: θ', 'B1: cooling in transfer'], aq='θ')
N('H', 6, 'In a continuous-flow heater, water flows at 0.015 kg s⁻¹ through a tube over a heater. With 150 W the outlet is 2.4 K hotter than the inlet; with 250 W it is 4.0 K hotter at the same flow rate. (a) Explain why the rate of heat loss is the same in both. (b) Use P = (dm/dt)cΔθ + h to find c. (c) Calculate the heat-loss rate h. Give only the answer to (b).', (250 - 150) / (0.015 * (4.0 - 2.4)), 'J kg⁻¹ K⁻¹',
  f'(a) The inlet and outlet temperatures, and so the temperature of the apparatus, are almost the same in both runs, so the heat-loss rate is taken to be the same. (b) 250 − 150 = 0.015 × c × (4.0 − 2.4), c = 100 ÷ 0.024 = {sf(100 / 0.024)} J kg⁻¹ K⁻¹. (c) h = 150 − 0.015 × {sf(100 / 0.024, 4)} × 2.4 = {sf(150 - 0.015 * 100 / 0.024 * 2.4)} W',
  ['B1: losses approximately equal', 'C1: two equations', 'M1: subtract', 'A1: c', 'C1: substitute back', 'A1: h'], aq='c')
N('H', 5, 'A 60 kg person drinks 0.50 kg of iced water at 2 °C. The body (c = 3500 J kg⁻¹ K⁻¹, temperature 37 °C) warms the water to 37 °C. (a) Calculate the energy needed to warm the water. (b) If none were replaced, calculate the fall in body temperature. (c) State how the body actually responds. Give only the answer to (b).' + WATER, 0.50 * CW * 35 / (60 * 3500), 'K',
  f'(a) E = 0.50 × 4200 × 35 = 73500 J. (b) Δθ = E/(mc) = 73500 ÷ (60 × 3500) = {sf(73500 / 210000)} K. (c) Metabolism increases (and blood flow to the skin falls) so the body temperature is kept almost constant.',
  ['C1: mcΔθ for water', 'A1: E', 'C1: Δθ = E/mc for body', 'A1: Δθ', 'B1: response'], aq='Δθ')
N('H', 6, 'Two blocks, A (0.50 kg, c = 900 J kg⁻¹ K⁻¹, at 80 °C) and B (1.5 kg, c = 450 J kg⁻¹ K⁻¹, at 20 °C), are placed in contact in an insulated box. (a) Calculate their heat capacities. (b) Calculate the final temperature. (c) Calculate the energy transferred from A to B. Give only the answer to (c).', 450 * (80 - (450 * 80 + 675 * 20) / 1125), 'J',
  f'(a) C_A = 0.50 × 900 = 450 J K⁻¹, C_B = 1.5 × 450 = 675 J K⁻¹. (b) θ = (450 × 80 + 675 × 20) ÷ (450 + 675) = {sf((450 * 80 + 675 * 20) / 1125)} °C. (c) E = C_A × (80 − θ) = 450 × (80 − {sf((450 * 80 + 675 * 20) / 1125, 4)}) = {sf(450 * (80 - 44))} J',
  ['A1: heat capacities', 'M1: weighted average', 'A1: θ', 'C1: E = CΔθ', 'C1: substitution', 'A1: E'], aq='E')
N('H', 5, 'A car radiator holds 6.0 kg of coolant (c = 3800 J kg⁻¹ K⁻¹). The engine supplies heat to it at 25 kW. (a) Calculate the rate of temperature rise if no heat is lost. (b) At steady state the radiator loses heat at 25 kW. Explain what this means for the coolant temperature. (c) If the fan fails and the loss falls to 15 kW, calculate the rate of temperature rise. Give only the answer to (c).', (25e3 - 15e3) / (6.0 * 3800), 'K s⁻¹',
  f'(a) dθ/dt = P/(mc) = 25000 ÷ (6.0 × 3800) = {sf(25000 / 22800)} K s⁻¹. (b) Gain equals loss, so the temperature stays constant (thermal steady state). (c) net 10 kW: dθ/dt = 10000 ÷ 22800 = {sf(10000 / 22800)} K s⁻¹',
  ['C1: dθ/dt = P/mc', 'A1: (a)', 'B1: constant temperature', 'C1: net power', 'A1: (c)'], aq='rate')

# ═════════════════════════ 19.5 Temperature scales (13/17/12) ═════════════════════════
lesson('19.5')
N('E', 1, 'Convert the boiling point of nitrogen, −196 °C, to kelvin.', -196 + 273.15, 'K', 'T = θ + 273.15 = −196 + 273.15 = 77.15 K', [], sig=3, aq='T')
N('E', 1, 'The surface of the Sun is at about 5800 K. Express this in degrees Celsius.', 5800 - 273, '°C', 'θ = T − 273 = 5800 − 273 = 5527 °C ≈ 5500 °C', [], sig=2, aq='θ')
M('E', 1, 'What is the temperature of absolute zero on the Celsius scale?', '−273.15 °C', ['0 °C', '−100 °C', '−459 °C'], 'T = 0 K corresponds to θ = −273.15 °C.')
M('E', 1, 'Why can there be no temperature below 0 K?', 'At absolute zero the internal energy of a system is a minimum; it cannot be reduced further', ['Thermometers cannot measure below 0 K', 'Gases condense at 0 K', 'The Celsius scale stops at −273 °C'], 'Absolute zero is the temperature at which the particles have minimum energy; nothing can be colder.')
N('E', 2, 'A gas cools by 35 °C. State its change in temperature in kelvin, and explain why.', 35, 'K', 'A change of 1 °C equals a change of 1 K (the scales have the same interval size): ΔT = 35 × 1 = 35 K', ['B1: equal-sized degrees'], sig=2, aq='ΔT')
M('E', 1, 'Which property is used in a liquid-in-glass thermometer as the thermometric property?', 'The expansion of the liquid', ['The colour of the liquid', 'The mass of the liquid', 'The density of the glass'], 'A thermometric property must change continuously and measurably with temperature: here, the length of the liquid column.')
M('E', 1, 'The thermodynamic temperature scale does not depend on the property of any particular substance. Why is this an advantage?', 'All correctly calibrated thermometers then agree at every temperature', ['It makes thermometers cheaper', 'It allows negative kelvin temperatures', 'It only works at 0 °C'], 'Scales based on, say, mercury expansion can disagree between fixed points; the thermodynamic scale is absolute.')
N('E', 1, 'Room temperature is 21 °C. Convert it to kelvin.', 21 + 273.15, 'K', 'T = 21 + 273.15 = 294.15 K ≈ 294 K', [], aq='T')
M('E', 1, 'Which two fixed points define the thermodynamic temperature scale in the 9702 course?', 'Absolute zero and the triple point of pure water (273.16 K)', ['0 °C and 100 °C', 'The boiling and freezing points of mercury', 'Absolute zero and 100 °C'], 'The kelvin is defined using absolute zero (0 K) and the triple point of water (273.16 K).')
N('E', 2, 'A freezer is at 255 K. What is this in °C?', 255 - 273.15, '°C', 'θ = T − 273.15 = 255 − 273.15 = −18 °C', ['C1: subtract 273.15'], sig=2, sign=True, aq='θ')
M('E', 1, 'Which property of a thermocouple is used to measure temperature?', 'The e.m.f. produced between its two junctions', ['Its length', 'Its resistance only', 'Its colour'], 'A thermocouple gives an e.m.f. that depends on the temperature difference between its junctions.')
N('E', 2, 'A temperature rises from 250 K to 310 K. Calculate the rise in °C.', 60, '°C', 'The interval is the same on both scales: Δθ = 310 − 250 = 60 °C', ['B1: equal intervals'], sig=2, aq='Δθ')
M('E', 1, 'A thermistor\'s resistance falls as temperature rises. Why is it useful as a thermometer?', 'Its resistance changes measurably and continuously with temperature', ['Its resistance is constant', 'It glows at high temperature', 'It produces an e.m.f.'], 'Any property that varies continuously and reproducibly with temperature can be used: here, resistance.')
N('E', 2, 'Liquid helium boils at 4.2 K. Express this in °C.', 4.2 - 273.15, '°C', 'θ = 4.2 − 273.15 = −268.95 °C ≈ −269 °C', ['C1: subtract 273.15'], sign=True, aq='θ')
# medium
N('M', 3, 'A resistance thermometer has resistance 100.0 Ω at 0 °C and 138.5 Ω at 100 °C. Assuming a linear scale, calculate the temperature when its resistance is 119.2 Ω.', (119.2 - 100.0) / (138.5 - 100.0) * 100, '°C',
  f'θ = (R − R₀)/(R₁₀₀ − R₀) × 100 = (119.2 − 100.0) ÷ (138.5 − 100.0) × 100 = {sf(19.2 / 38.5 * 100)} °C', ['C1: linear interpolation formula', 'C1: substitution', 'C1: × 100'], aq='θ')
N('M', 3, 'A liquid-in-glass thermometer has a 4.0 cm column at 0 °C and 24.0 cm at 100 °C. What temperature is shown when the column is 15.0 cm long?', (15.0 - 4.0) / 20.0 * 100, '°C', 'θ = (15.0 − 4.0) ÷ (24.0 − 4.0) × 100 = 55 °C', ['C1: length change from 0 °C', 'C1: fraction of the interval', 'C1: × 100'], sig=2, aq='θ')
M('M', 4, 'A thermistor and a resistance-wire thermometer are calibrated at 0 °C and 100 °C. At 50 °C (measured by a gas thermometer) they read different values. Why?', 'Their resistances do not vary linearly with temperature in the same way, so a linear scale between fixed points gives different readings', ['One of them is broken', 'Thermistors cannot measure 50 °C', 'Resistance does not depend on temperature'], 'Scales based on different thermometric properties agree only at the fixed points unless each property varies linearly with true temperature.', ['C1: different property–temperature relations', 'C1: non-linear', 'C1: agree only at fixed points'])
N('M', 3, 'A gas thermometer at constant volume shows a pressure of 1.00 × 10⁵ Pa at the triple point of water (273.16 K). In a hot liquid the pressure is 1.36 × 10⁵ Pa. Calculate the temperature of the liquid in kelvin.', 273.16 * 1.36, 'K', 'T = 273.16 × p/p_tr = 273.16 × 1.36 ÷ 1.00 = 371.5 K', ['C1: T ∝ p at constant volume', 'C1: substitution'], aq='T')
N('M', 4, 'A thermocouple gives 0.0 mV at 0 °C and 4.1 mV at 100 °C. Assuming a linear response, calculate the temperature when the e.m.f. is 2.9 mV, and convert it to kelvin. Give the temperature in kelvin.', 2.9 / 4.1 * 100 + 273.15, 'K', f'θ = 2.9 ÷ 4.1 × 100 = {sf(2.9 / 4.1 * 100)} °C. T = {sf(2.9 / 4.1 * 100, 4)} + 273.15 = {sf(2.9 / 4.1 * 100 + 273.15)} K', ['C1: linear interpolation', 'C1: °C', 'C1: + 273.15'], aq='T')
M('M', 3, 'Which statement about the kelvin and Celsius scales is correct?', 'A temperature difference has the same value in K and in °C', ['A temperature has the same numerical value on both scales', '0 K equals 0 °C', '100 K equals 100 °C'], 'T(K) = θ(°C) + 273.15: values differ by 273.15, but intervals are equal.', ['C1: equal intervals', 'C1: offset 273.15'])
N('M', 3, 'The temperature of a gas doubles from 300 K. What is its new temperature in °C?', 600 - 273, '°C', 'New T = 2 × 300 = 600 K. θ = 600 − 273 = 327 °C', ['C1: double the kelvin value', 'C1: convert'], aq='θ')
M('M', 4, 'A student says that heating water from 10 °C to 20 °C "doubles its temperature". Why is this wrong?', 'In kelvin the temperature rises from 283 K to 293 K, only about 3.5 % higher', ['It is correct', 'The Celsius scale has no zero', 'Water cannot be heated from 10 °C'], 'Ratios of temperatures are only meaningful on an absolute scale: 293 ÷ 283 = 1.035.', ['C1: convert to kelvin', 'C1: ratio 1.035', 'C1: absolute scale needed for ratios'])
N('M', 3, 'A platinum resistance thermometer reads 108.0 Ω in a cold bath and 136.0 Ω in boiling water (100 °C). Its resistance at 0 °C is 100.0 Ω. Calculate the cold bath temperature on the platinum scale.', (108.0 - 100.0) / (136.0 - 100.0) * 100, '°C', 'θ = (108.0 − 100.0) ÷ (136.0 − 100.0) × 100 = 22.2 °C', ['C1: interpolation', 'C1: substitution'], aq='θ')
N('E', 2, 'Express the triple point of water, 273.16 K, in degrees Celsius.', 273.16 - 273.15, '°C', 'θ = 273.16 − 273.15 = 0.01 °C', ['C1: subtract 273.15'], sig=1, aq='θ')
M('M', 3, 'Which of these is NOT a suitable thermometric property?', 'The mass of an object', ['The volume of a gas at constant pressure', 'The resistance of a metal wire', 'The e.m.f. of a thermocouple'], 'Mass does not change with temperature, so it cannot indicate temperature.', ['C1: must vary with temperature', 'C1: mass does not'])
N('M', 4, 'A constant-pressure gas thermometer has a volume of 250 cm³ at 0 °C (273 K). At an unknown temperature the volume is 340 cm³. Calculate the temperature in °C.', 273 * 340 / 250 - 273, '°C', 'T ∝ V: T = 273 × 340 ÷ 250 = 371.3 K. θ = 371.3 − 273 = 98.3 °C', ['C1: V ∝ T', 'C1: T in K', 'C1: convert'], aq='θ')
M('M', 3, 'Why is a thermocouple, rather than a liquid-in-glass thermometer, used to measure the temperature of a furnace at 1200 °C?', 'It can work at very high temperatures and gives an electrical output that responds quickly', ['It is more accurate at room temperature', 'It needs no wires', 'Liquid thermometers are too accurate'], 'Glass and liquids fail at high temperature; a thermocouple of suitable metals survives and responds fast.', ['C1: high temperature range', 'C1: fast/electrical output'])
N('M', 3, 'A temperature of 77 K is measured in liquid nitrogen. By how many kelvin must it be warmed to reach 20 °C?', 293 - 77, 'K', '20 °C = 293 K, so ΔT = 293 − 77 = 216 K', ['C1: convert 20 °C', 'C1: difference'], aq='ΔT')
N('M', 3, 'On an empirical scale based on a gas thermometer, T = 273.16 × (p/p_tr). Find the pressure ratio p/p_tr at the boiling point of water (373.15 K).', 373.15 / 273.16, None, 'p/p_tr = T/273.16 = 373.15 ÷ 273.16 = 1.366', ['C1: rearranged', 'C1: substitution'], sig=4, aq='ratio')
M('M', 3, 'Two thermometers based on different properties are both calibrated at the ice and steam points. When might they disagree?', 'At temperatures between and beyond the fixed points, if their properties vary non-linearly', ['Only at the ice point', 'Only at the steam point', 'Never'], 'Calibration forces agreement only at the fixed points.', ['C1: agree at fixed points', 'C1: may disagree elsewhere'])
# hard
N('H', 5, 'A thermistor has resistance 5.0 kΩ at 0 °C and 0.50 kΩ at 100 °C. At an unknown temperature it reads 1.5 kΩ. (a) Calculate the temperature assuming a linear scale. (b) The true temperature (from a gas thermometer) is 46 °C. Explain the difference. (c) State one advantage and one disadvantage of a thermistor. Give only the answer to (a).', (5.0 - 1.5) / (5.0 - 0.50) * 100, '°C',
  f'(a) θ = (5.0 − 1.5) ÷ (5.0 − 0.50) × 100 = {sf(3.5 / 4.5 * 100)} °C. (b) The thermistor\'s resistance varies non-linearly (roughly exponentially) with temperature, so a linear scale between the fixed points is wrong. (c) Advantage: very sensitive/fast. Disadvantage: non-linear, needs calibration.',
  ['C1: linear interpolation (resistance falls)', 'A1: θ', 'B1: non-linear', 'B1: advantage', 'B1: disadvantage'], aq='θ')
N('H', 6, 'A constant-volume gas thermometer reads p = 1.098 × 10⁵ Pa at the triple point of water (273.16 K) and 1.500 × 10⁵ Pa in a liquid. (a) Calculate the temperature of the liquid in K. (b) Convert it to °C. (c) Explain why the gas thermometer is used to calibrate other thermometers. Give only the answer to (b).', 273.16 * 1.500 / 1.098 - 273.15, '°C',
  f'(a) T = 273.16 × 1.500 ÷ 1.098 = {sf(273.16 * 1.5 / 1.098, 4)} K. (b) θ = {sf(273.16 * 1.5 / 1.098, 4)} − 273.15 = {sf(273.16 * 1.5 / 1.098 - 273.15)} °C. (c) An ideal gas thermometer agrees with the thermodynamic scale, independent of the gas used, at low pressure.',
  ['C1: T ∝ p', 'A1: T', 'C1: subtract 273.15', 'A1: θ', 'B1: matches thermodynamic scale', 'B1: independent of gas'], aq='θ')
N('H', 5, 'A thermocouple\'s e.m.f. follows E = aθ + bθ², with a = 40 µV K⁻¹ and b = 0.040 µV K⁻² (θ in °C). (a) Calculate E at 100 °C. (b) Calculate E at 50 °C. (c) Find the temperature a linear scale calibrated at 0 and 100 °C would show when the true temperature is 50 °C. Give only the answer to (c).', (40 * 50 + 0.04 * 2500) / (40 * 100 + 0.04 * 10000) * 100, '°C',
  f'(a) E = 40 × 100 + 0.040 × 100² = 4400 µV. (b) E = 40 × 50 + 0.040 × 50² = 2100 µV. (c) linear reading = 2100 ÷ 4400 × 100 = {sf(2100 / 4400 * 100)} °C',
  ['C1: substitution at 100 °C', 'A1: 4400 µV', 'A1: 2100 µV', 'C1: proportion of the interval', 'A1: θ'], aq='θ')
N('H', 6, 'Air in a sealed flask is at 20 °C and 1.00 × 10⁵ Pa. The flask is heated at constant volume. (a) Explain why pressure is proportional to kelvin temperature, not Celsius temperature. (b) Calculate the pressure at 100 °C. (c) Calculate the temperature in °C at which the pressure would double. Give only the answer to (c).', 2 * 293.15 - 273.15, '°C',
  f'(a) p ∝ T only when T is measured from absolute zero, where p → 0. (b) p = 1.00 × 10⁵ × 373.15 ÷ 293.15 = {sf(1e5 * 373.15 / 293.15)} Pa. (c) Double p needs double T: 2 × 293.15 = 586.3 K, θ = 586.3 − 273.15 = {sf(2 * 293.15 - 273.15)} °C',
  ['B1: proportional to absolute temperature', 'C1: p₂ = p₁T₂/T₁', 'A1: p', 'C1: double T in kelvin', 'C1: convert', 'A1: θ'], aq='θ')
N('H', 5, 'The resistance R of a copper wire varies as R = R₀(1 + αθ), with α = 4.3 × 10⁻³ K⁻¹ and R₀ = 12.0 Ω at 0 °C. (a) Calculate R at 100 °C. (b) The wire is in a furnace and R = 40.0 Ω. Calculate θ. (c) Convert θ to kelvin. Give only the answer to (b).', (40.0 / 12.0 - 1) / 4.3e-3, '°C',
  f'(a) R = 12.0 × (1 + 4.3 × 10⁻³ × 100) = {sf(12 * 1.43)} Ω. (b) θ = (R/R₀ − 1)/α = (40.0 ÷ 12.0 − 1) ÷ 4.3 × 10⁻³ = {sf((40 / 12 - 1) / 4.3e-3)} °C. (c) T = {sf((40 / 12 - 1) / 4.3e-3, 4)} + 273 = {sf((40 / 12 - 1) / 4.3e-3 + 273)} K',
  ['A1: R at 100 °C', 'M1: rearranged', 'C1: substitution', 'A1: θ', 'B1: T'], aq='θ')
N('H', 6, 'A student uses the expansion of alcohol in a thermometer. Between 0 °C and 100 °C the column grows from 2.0 cm to 22.0 cm, but at the true temperature 50 °C it is 11.5 cm. (a) Calculate the temperature this thermometer indicates at 11.5 cm. (b) Calculate the error. (c) Explain what this tells you about alcohol\'s expansion. Give only the answer to (b).', (11.5 - 2.0) / 20.0 * 100 - 50, '°C',
  f'(a) θ = (11.5 − 2.0) ÷ 20.0 × 100 = {sf(9.5 / 20 * 100)} °C. (b) error = {sf(47.5)} − 50 = {sf(47.5 - 50)} °C. (c) Alcohol\'s expansion is not exactly linear with temperature: it expands less per kelvin at lower temperatures.',
  ['C1: interpolation', 'A1: 47.5 °C', 'C1: error', 'A1: −2.5 °C', 'B1: non-linear expansion', 'B1: direction'], sign=True, aq='error')
N('H', 5, 'Mercury freezes at −39 °C and boils at 357 °C. (a) Express both in kelvin. (b) Explain why a mercury thermometer cannot measure the temperature of liquid nitrogen (77 K). (c) Calculate the range of a mercury thermometer in kelvin. Give only the answer to (c).', 357 - (-39), 'K',
  '(a) 234 K and 630 K. (b) 77 K is below 234 K, so the mercury would be solid. (c) range = 357 − (−39) = 396 K (equal to 396 °C because intervals are equal)',
  ['A1: both in K', 'B1: mercury freezes', 'C1: difference', 'A1: range', 'B1: equal intervals'], aq='range')
N('H', 6, 'A sealed bottle of air is put in a freezer at −18 °C after being filled at 22 °C and 1.01 × 10⁵ Pa. (a) Calculate the pressure inside at −18 °C. (b) Calculate the force on the 4.0 cm diameter cap due to the pressure difference. (c) Explain why using Celsius temperatures in p₁/T₁ = p₂/T₂ gives a meaningless answer. Give only the answer to (b).', (1.01e5 - 1.01e5 * 255.15 / 295.15) * pi * 0.02 ** 2, 'N',
  f'(a) p = 1.01 × 10⁵ × 255.15 ÷ 295.15 = {sf(1.01e5 * 255.15 / 295.15)} Pa. (b) Δp = 1.01 × 10⁵ − {sf(1.01e5 * 255.15 / 295.15, 4)} = {sf(1.01e5 * (1 - 255.15 / 295.15))} Pa, area = π × 0.020² = {sf(pi * 4e-4)} m², F = {sf(1.01e5 * (1 - 255.15 / 295.15), 4)} × {sf(pi * 4e-4, 4)} = {sf(1.01e5 * (1 - 255.15 / 295.15) * pi * 4e-4)} N (inwards). (c) The Celsius value −18 would give a negative pressure: p ∝ T only for absolute temperature.',
  ['C1: p₂ = p₁T₂/T₁ in kelvin', 'A1: p', 'C1: Δp', 'C1: F = ΔpA', 'A1: F', 'B1: Celsius gives negative/meaningless'], aq='F')

# ═════════════════════════ 19.6 Specific heat capacity and latent heat (16/16/10) ═════════════════════════
lesson('19.6')
N('E', 2, 'A swimming pool holds 3.0 × 10⁵ kg of water. Calculate the energy needed to warm it by 2.0 K.' + WATER, 3.0e5 * CW * 2, 'J', f'E = mcΔθ = 3.0 × 10⁵ × 4200 × 2.0 = {sf(3e5 * 4200 * 2)} J', ['C1: E = mcΔθ'], aq='E')
N('E', 2, 'A 0.50 kg steel bolt (c = 450 J kg⁻¹ K⁻¹) absorbs 9000 J. Calculate its temperature rise.', 9000 / (0.5 * 450), 'K', 'Δθ = E/(mc) = 9000 ÷ (0.50 × 450) = 40 K', ['C1: Δθ = E/mc'], sig=2, aq='Δθ')
M('E', 1, 'A data book lists a value of 900 J kg⁻¹ K⁻¹ for aluminium. What does this specific heat capacity tell you?', '900 J is needed to raise the temperature of 1 kg of aluminium by 1 K', ['900 J is needed to melt 1 kg of aluminium', '1 kg of aluminium contains 900 J of energy', 'Aluminium melts at 900 K'], 'Specific heat capacity c = E/(mΔθ) is the energy per kilogram per kelvin of temperature rise.')
M('E', 1, 'What is the SI unit of specific heat capacity?', 'J kg⁻¹ K⁻¹', ['J kg⁻¹', 'J K⁻¹', 'W kg⁻¹'], 'c = E/(mΔθ): joules per kilogram per kelvin.')
N('E', 2, 'A 1.5 kg block absorbs 54 000 J and warms by 40 K. Calculate the specific heat capacity of its material.', 54000 / (1.5 * 40), 'J kg⁻¹ K⁻¹', 'c = E/(mΔθ) = 54000 ÷ (1.5 × 40) = 900 J kg⁻¹ K⁻¹', ['C1: c = E/mΔθ'], sig=2, aq='c')
M('E', 1, 'Why is water used as the coolant in car engines?', 'Its high specific heat capacity lets it absorb a lot of energy for a small temperature rise', ['It has a low boiling point', 'It is a good insulator', 'It has a low specific heat capacity'], 'c ≈ 4200 J kg⁻¹ K⁻¹ is among the highest of common liquids.')
N('E', 2, 'Calculate the energy needed to heat 0.75 kg of milk (c = 3900 J kg⁻¹ K⁻¹) from 5 °C to 65 °C.', 0.75 * 3900 * 60, 'J', 'E = mcΔθ = 0.75 × 3900 × 60 = 175500 J', ['C1: Δθ = 60 K'], aq='E')
N('E', 2, 'A 1.2 kW heater warms a 2.0 kg block of oil for 3.0 minutes. Calculate the energy supplied.', 1200 * 180, 'J', 'E = Pt = 1200 × 180 = 216000 J', ['C1: t in s'], aq='E')
M('E', 1, 'Why does the sea warm up more slowly than the land on a sunny day?', 'Water has a much higher specific heat capacity than rock and soil', ['The sea reflects all the sunlight', 'Land has a higher specific heat capacity', 'The sea is colder'], 'The same energy per kilogram produces a smaller temperature rise in water.')
N('E', 2, 'How much energy is released when 0.30 kg of water cools from 90 °C to 20 °C?' + WATER, 0.30 * CW * 70, 'J', 'E = mcΔθ = 0.30 × 4200 × 70 = 88200 J', ['C1: E = mcΔθ'], aq='E')
M('E', 1, 'Which quantity is measured in J kg⁻¹?', 'Specific latent heat', ['Specific heat capacity', 'Heat capacity', 'Internal energy'], 'L = E/m has no temperature in it: J kg⁻¹.')
N('E', 2, 'A 3.0 kW kettle runs for 2.0 minutes and heats 1.0 kg of water. Calculate the temperature rise, assuming no losses.' + WATER, 3000 * 120 / (1.0 * CW), 'K', 'E = Pt = 3000 × 120 = 360000 J. Δθ = 360000 ÷ (1.0 × 4200) = 85.7 K', ['C1: E = Pt', 'C1: Δθ = E/mc'], aq='Δθ')
M('E', 1, 'An object\'s heat capacity C is related to its mass m and specific heat capacity c by…', 'C = mc', ['C = c/m', 'C = m/c', 'C = mc²'], 'Heat capacity is the energy per kelvin for the whole object: C = mc.')
N('E', 2, 'Calculate the heat capacity of a 0.80 kg copper saucepan (c = 385 J kg⁻¹ K⁻¹).', 0.80 * 385, 'J K⁻¹', 'C = mc = 0.80 × 385 = 308 J K⁻¹', ['C1: C = mc'], aq='C')
N('E', 2, 'A 0.25 kg block of ice at 0 °C is melted by a 500 W heater. Calculate the time taken, assuming no losses.' + FUSION, 0.25 * LF / 500, 's', f'E = mL = 0.25 × 3.34 × 10⁵ = {sf(0.25 * LF)} J. t = E/P = {sf(0.25 * LF)} ÷ 500 = {sf(0.25 * LF / 500)} s', ['C1: E = mL, t = E/P'], aq='t')
M('E', 1, 'The specific heat capacity of aluminium is about twice that of iron. Equal masses of each receive the same energy. Which is correct?', 'The iron\'s temperature rises about twice as much', ['The aluminium\'s temperature rises twice as much', 'Both rise by the same amount', 'Neither temperature rises'], 'Δθ = E/(mc): half the c gives twice the Δθ.')
# medium
N('M', 3, 'In an electrical method, a 40 W heater in a 1.0 kg aluminium block raises its temperature by 12.5 K in 300 s. Calculate the specific heat capacity of aluminium.', 40 * 300 / (1.0 * 12.5), 'J kg⁻¹ K⁻¹', 'E = Pt = 40 × 300 = 12000 J. c = E/(mΔθ) = 12000 ÷ (1.0 × 12.5) = 960 J kg⁻¹ K⁻¹', ['C1: E = Pt', 'C1: c = E/mΔθ', 'C1: substitution'], aq='c')
N('M', 4, 'A heater runs at 12 V and 4.0 A for 5.0 minutes in a 0.80 kg block, raising its temperature from 18 °C to 36 °C. Calculate the specific heat capacity of the block material.', 12 * 4.0 * 300 / (0.80 * 18), 'J kg⁻¹ K⁻¹', 'E = VIt = 12 × 4.0 × 300 = 14400 J. c = 14400 ÷ (0.80 × 18) = 1000 J kg⁻¹ K⁻¹', ['C1: E = VIt', 'C1: Δθ = 18 K', 'C1: c = E/mΔθ'], aq='c')
M('M', 3, 'In an electrical heating experiment the measured specific heat capacity of a metal block is larger than the accepted value. Why?', 'Energy is lost to the surroundings, so less energy actually heats the block than the electrical energy counted', ['The thermometer reads too high', 'The block is too light', 'The current was too small'], 'c = E/(mΔθ): Δθ is smaller than it would be with no losses, so c comes out too large.', ['C1: energy lost', 'C1: Δθ too small', ])
N('M', 3, 'A solar water heater raises the temperature of 150 kg of water from 15 °C to 55 °C in one day. Calculate the energy absorbed.' + WATER, 150 * CW * 40, 'J', 'E = mcΔθ = 150 × 4200 × 40 = 2.52 × 10⁷ J', ['C1: Δθ = 40 K', 'C1: E = mcΔθ'], aq='E')
N('M', 4, 'A 2.4 kW kettle containing 1.7 kg of water at 18 °C takes 4.5 minutes to reach 100 °C. Calculate the efficiency of the kettle.' + WATER, 1.7 * CW * 82 / (2400 * 270) * 100, '%', f'Useful energy = 1.7 × 4200 × 82 = {sf(1.7 * 4200 * 82)} J. Input = 2400 × 270 = {sf(648000)} J. Efficiency = {sf(1.7 * 4200 * 82, 4)} ÷ 648000 × 100 = {sf(1.7 * 4200 * 82 / 648000 * 100)} %', ['C1: useful energy', 'C1: input energy', 'C1: ratio × 100'], aq='efficiency')
M('M', 3, 'Why does a temperature–time graph for a heated block often curve and level off rather than rising in a straight line?', 'As the block gets hotter it loses energy to the surroundings faster', ['The specific heat capacity becomes zero', 'The heater power increases', 'The block\'s mass decreases'], 'Heat loss increases with the temperature difference from the surroundings, so the rate of rise falls.', ['C1: losses increase with temperature', 'C1: rate of rise falls'])
N('M', 3, 'A 1.2 kg block of iron (c = 450 J kg⁻¹ K⁻¹) at 200 °C cools to 25 °C. Calculate the energy released and the mass of ice at 0 °C it could melt. Give the mass of ice.' + FUSION, 1.2 * 450 * 175 / LF, 'kg', f'E = 1.2 × 450 × 175 = {sf(94500)} J. Mass of ice = E/L = {sf(94500, 4)} ÷ 3.34 × 10⁵ = {sf(94500 / LF)} kg', ['C1: E = mcΔθ', 'C1: m = E/L', 'C1: substitution'], aq='m')
N('M', 4, 'A heat pack contains 0.15 kg of a salt solution that solidifies at 54 °C, releasing latent heat of 2.6 × 10⁵ J kg⁻¹, then cools to 30 °C (c of solid = 2200 J kg⁻¹ K⁻¹). Calculate the total energy released.', 0.15 * 2.6e5 + 0.15 * 2200 * 24, 'J', 'Freezing: 0.15 × 2.6 × 10⁵ = 39000 J. Cooling: 0.15 × 2200 × 24 = 7920 J. Total = 39000 + 7920 = 46920 J', ['C1: mL', 'C1: mcΔθ', 'C1: total'], aq='E')
M('M', 3, 'A cup of tea at 80 °C has a few ice cubes added. Which process absorbs the most energy per kilogram of ice?', 'Melting the ice', ['Warming the ice from −5 °C to 0 °C', 'Warming the melted ice from 0 °C to 10 °C', 'Cooling the tea by 1 K'], 'L_f = 3.34 × 10⁵ J kg⁻¹ is much larger than c × Δθ for small Δθ (2100 × 5 or 4200 × 10).', ['C1: compare mL with mcΔθ', 'C1: latent heat largest'])
N('M', 3, 'A 70 kg person has an average specific heat capacity of 3500 J kg⁻¹ K⁻¹. During exercise their temperature rises by 1.5 K. Calculate the energy stored in the body.', 70 * 3500 * 1.5, 'J', 'E = mcΔθ = 70 × 3500 × 1.5 = 367500 J', ['C1: E = mcΔθ', 'C1: substitution'], aq='E')
N('M', 4, 'Water flows through a 9.0 kW electric shower at 0.050 kg s⁻¹, entering at 12 °C. Calculate the outlet temperature, assuming no losses.' + WATER, 12 + 9000 / (0.050 * CW), '°C', 'P = (m/t)cΔθ, so Δθ = 9000 ÷ (0.050 × 4200) = 42.9 K. Outlet = 12 + 42.9 = 54.9 °C', ['C1: P = (m/t)cΔθ', 'C1: Δθ', 'C1: add to inlet'], aq='θ')
M('M', 3, 'Why does sweating cool the body much more than the same mass of water simply warming up on the skin?', 'Evaporation takes the latent heat of vaporisation, which is far larger than cΔθ for a few kelvin', ['Sweat is colder than water', 'Sweat has a lower specific heat capacity', 'Evaporation adds energy to the body'], 'Each kg evaporated removes about 2.4 MJ; warming 1 kg of water by 5 K removes only 21 kJ.', ['C1: latent heat', 'C1: much larger than mcΔθ'])
N('M', 3, 'The temperature of a 0.50 kg block rises by 8.0 K when a 25 W heater runs for 160 s. Calculate the heat capacity of the block, and its specific heat capacity. Give the specific heat capacity.', 25 * 160 / 8.0 / 0.50, 'J kg⁻¹ K⁻¹', 'C = E/Δθ = 25 × 160 ÷ 8.0 = 500 J K⁻¹. c = C/m = 500 ÷ 0.50 = 1000 J kg⁻¹ K⁻¹', ['C1: E = Pt', 'C1: C = E/Δθ', 'C1: c = C/m'], aq='c')
N('M', 4, 'A 500 g mug of tea at 85 °C is left to cool to 45 °C. Treat it as water. The mug itself (0.30 kg, c = 800 J kg⁻¹ K⁻¹) also cools. Calculate the total energy lost to the room.' + WATER, 0.5 * CW * 40 + 0.3 * 800 * 40, 'J', 'Tea: 0.50 × 4200 × 40 = 84000 J. Mug: 0.30 × 800 × 40 = 9600 J. Total = 84000 + 9600 = 93600 J', ['C1: tea', 'C1: mug', 'C1: total'], aq='E')
M('M', 3, 'Which two measurements, besides the mass, are needed to find a specific heat capacity by the electrical method?', 'The electrical energy supplied (V, I, t) and the temperature rise', ['The volume and density of the block', 'The latent heat and the final temperature', 'The resistance of the heater only'], 'c = E/(mΔθ) and the electrical energy supplied is E = VIt, so c = VIt/(mΔθ): you need the energy supplied (voltage, current and time) and the rise in temperature.', ['C1: energy input', 'C1: temperature rise'])
N('M', 3, 'A 0.20 kg block of ice at −20 °C is warmed to 0 °C and melted. c_ice = 2100 J kg⁻¹ K⁻¹. Calculate the total energy needed.' + FUSION, 0.2 * CICE * 20 + 0.2 * LF, 'J', f'Warming: 0.20 × 2100 × 20 = 8400 J. Melting: 0.20 × 3.34 × 10⁵ = {sf(0.2 * LF)} J. Total = 8400 + {sf(0.2 * LF, 4)} = {sf(0.2 * CICE * 20 + 0.2 * LF)} J', ['C1: mcΔθ', 'C1: mL', 'C1: total'], aq='E')
# hard
N('H', 6, 'A student heats 0.50 kg of water in a 0.20 kg aluminium pan (c = 900 J kg⁻¹ K⁻¹) on a 1.2 kW hotplate. Both start at 20 °C. (a) Calculate the energy to bring both to 100 °C. (b) Calculate the time taken, assuming 70 % efficiency. (c) The hotplate is left on. Calculate the extra time to boil away 0.10 kg of water. Give only the answer to (c).' + WATER + VAPOUR, 0.10 * LV / (0.70 * 1200), 's',
  f'(a) water: 0.50 × 4200 × 80 = 168000 J, pan: 0.20 × 900 × 80 = 14400 J, total = {sf(182400)} J. (b) useful power = 0.70 × 1200 = 840 W, t = 182400 ÷ 840 = {sf(182400 / 840)} s. (c) E = 0.10 × 2.26 × 10⁶ = {sf(0.1 * LV)} J, t = {sf(0.1 * LV)} ÷ 840 = {sf(0.1 * LV / 840)} s',
  ['C1: water and pan', 'A1: total energy', 'C1: useful power', 'A1: t', 'C1: E = mL_v', 'A1: extra time'], aq='t')
N('H', 5, 'A copper block of mass 0.60 kg is heated by a 50 W heater. A graph of temperature against time is a straight line of gradient 0.20 K s⁻¹ for the first few minutes. (a) Calculate c for copper from this gradient. (b) Explain why only the early part of the graph is used. (c) The accepted value is 385 J kg⁻¹ K⁻¹. Calculate the percentage difference. Give only the answer to (a).', 50 / (0.60 * 0.20), 'J kg⁻¹ K⁻¹',
  f'(a) P = mc(dθ/dt), so c = P/(m × gradient) = 50 ÷ (0.60 × 0.20) = {sf(50 / 0.12)} J kg⁻¹ K⁻¹. (b) At first the block is close to room temperature, so heat losses are smallest. (c) ({sf(50 / 0.12, 4)} − 385) ÷ 385 × 100 = {sf((50 / 0.12 - 385) / 385 * 100)} %',
  ['C1: P = mc dθ/dt', 'A1: c', 'B1: small losses early on', 'C1: percentage difference', 'A1: value'], aq='c')
N('H', 6, 'An ice cream maker removes energy from 1.0 kg of mixture (c = 3300 J kg⁻¹ K⁻¹, L_f = 2.0 × 10⁵ J kg⁻¹, freezes at −2 °C) starting at 18 °C, freezing all of it and cooling it to −10 °C (c of frozen = 1800 J kg⁻¹ K⁻¹). (a) Calculate the energy removed in each stage. (b) Calculate the total. (c) The freezer removes 150 W. Calculate the time taken in minutes. Give only the answer to (c).', (1.0 * 3300 * 20 + 1.0 * 2.0e5 + 1.0 * 1800 * 8) / 150 / 60, 'minutes',
  f'(a) cool liquid 18 → −2 °C: 1.0 × 3300 × 20 = 66000 J; freeze: 1.0 × 2.0 × 10⁵ = 200000 J; cool solid −2 → −10 °C: 1.0 × 1800 × 8 = 14400 J. (b) total = 66000 + 200000 + 14400 = 280400 J. (c) t = 280400 ÷ 150 = {sf(280400 / 150)} s. In minutes: {sf(280400 / 150, 4)} ÷ 60 = {sf(280400 / 9000)}',
  ['C1: liquid cooling', 'C1: freezing', 'C1: solid cooling', 'A1: total', 'C1: t = E/P', 'A1: minutes'], aq='t')
N('H', 5, 'A geothermal power plant takes hot water at 180 °C from underground at 50 kg s⁻¹ and returns it at 80 °C. (a) Calculate the rate at which thermal energy is extracted (c = 4200 J kg⁻¹ K⁻¹). (b) The plant is 15 % efficient. Calculate the electrical power output. (c) Explain why the water must be kept under pressure. Give only the answer to (b).', 0.15 * 50 * CW * 100, 'W',
  f'(a) P = (m/t)cΔθ = 50 × 4200 × 100 = {sf(50 * 4200 * 100)} W. (b) 0.15 × {sf(2.1e7, 4)} = {sf(0.15 * 2.1e7)} W. (c) At atmospheric pressure water boils at 100 °C; pressure keeps it liquid at 180 °C.',
  ['C1: (m/t)cΔθ', 'A1: thermal power', 'C1: × efficiency', 'A1: electrical power', 'B1: boiling point raised by pressure'], aq='P')
N('H', 6, 'A 0.050 kg lead bullet (c = 130 J kg⁻¹ K⁻¹, melting point 327 °C, L_f = 2.5 × 10⁴ J kg⁻¹) at 27 °C hits a steel plate at speed v and stops. Assume all its kinetic energy becomes its internal energy. (a) Calculate the energy to raise it to its melting point. (b) Calculate the energy to melt it completely. (c) Calculate the minimum speed for the bullet to melt completely. Give only the answer to (c).', sqrt(2 * (0.05 * 130 * 300 + 0.05 * 2.5e4) / 0.05), 'm s⁻¹',
  f'(a) 0.050 × 130 × 300 = 1950 J. (b) 0.050 × 2.5 × 10⁴ = 1250 J. (c) ½mv² = 1950 + 1250 = 3200 J, v = √(2 × 3200 ÷ 0.050) = {sf(sqrt(6400 / 0.05))} m s⁻¹',
  ['C1: mcΔθ', 'A1: 1950 J', 'A1: 1250 J', 'M1: ½mv² = total', 'C1: rearranged', 'A1: v'], aq='v')

# ── extras 2 ──
lesson('19.2')
N('H', 5, 'A gas in a cylinder at 1.0 × 10⁵ Pa occupies 2.4 × 10⁻³ m³. It is compressed at constant pressure to 1.6 × 10⁻³ m³ while 140 J leaves by heating, and then heated at constant volume with 260 J. (a) Calculate the work done on the gas in the first stage. (b) Calculate ΔU for each stage. (c) Calculate the total ΔU. Give only the answer to (c).', 1.0e5 * 0.8e-3 - 140 + 260, 'J',
  '(a) w = pΔV = 1.0 × 10⁵ × 0.8 × 10⁻³ = 80 J (on the gas). (b) Stage 1: ΔU = −140 + 80 = −60 J. Stage 2: w = 0, ΔU = 260 J. (c) total = −60 + 260 = 200 J',
  ['A1: w = 80 J', 'C1: stage 1 ΔU', 'C1: stage 2 w = 0', 'A1: stage values', 'A1: total'], sig=2, aq='ΔU')
N('H', 6, 'An inflatable mattress is pumped up. The pump does 3.2 kJ of work on the air, and the air does 1.8 kJ of work pushing back the atmosphere as the mattress swells. The air loses 0.6 kJ by heating. (a) Calculate the net work done on the air. (b) Calculate ΔU of the air. (c) Explain whether the air ends up warmer or cooler than at the start. Give only the answer to (b).', 3200 - 1800 - 600, 'J',
  '(a) w = 3200 − 1800 = 1400 J. (b) ΔU = q + w = −600 + 1400 = 800 J. (c) ΔU > 0 for the air that entered (an ideal-gas model links U to T), so it is warmer.',
  ['C1: net w', 'A1: 1400 J', 'C1: ΔU = q + w', 'A1: 800 J', 'B1: warmer', 'B1: reason'], sig=2, aq='ΔU')

lesson('19.3')
N('H', 5, 'A cylinder holds 0.20 mol of helium at 300 K. 250 J of heat is supplied and the gas does 100 J of work. (a) Calculate ΔU. (b) Calculate the final temperature using ΔU = (3/2)nRΔT. (c) Calculate the mean kinetic energy per atom at the final temperature using (3/2)kT. Give only the answer to (b).' + take('R', 'k'), 300 + 150 / (1.5 * 0.20 * 8.31), 'K',
  f'(a) ΔU = 250 − 100 = 150 J. (b) ΔT = 150 ÷ (1.5 × 0.20 × 8.31) = {sf(150 / (0.3 * 8.31))} K, T = 300 + {sf(150 / (0.3 * 8.31), 4)} = {sf(300 + 150 / (0.3 * 8.31))} K. (c) ⟨Ek⟩ = 1.5 × 1.38 × 10⁻²³ × {sf(300 + 150 / (0.3 * 8.31), 4)} = {sf(1.5 * 1.38e-23 * (300 + 150 / (0.3 * 8.31)))} J',
  ['A1: ΔU', 'C1: ΔT', 'A1: T', 'C1: (3/2)kT', 'A1: ⟨Ek⟩'], aq='T')

lesson('19.4')
N('H', 5, 'A 0.12 kg block of an unknown metal at 98 °C is placed in 0.15 kg of water at 22 °C in a 0.080 kg copper calorimeter (c = 390 J kg⁻¹ K⁻¹), also at 22 °C. The final temperature is 26 °C. (a) Calculate the energy gained by the water and calorimeter. (b) Calculate c for the metal. (c) Suggest which metal it might be. Give only the answer to (b).' + WATER, (0.15 * CW + 0.08 * 390) * 4 / (0.12 * 72), 'J kg⁻¹ K⁻¹',
  f'(a) (0.15 × 4200 + 0.080 × 390) × 4 = {sf((630 + 31.2) * 4)} J. (b) c = {sf((630 + 31.2) * 4, 4)} ÷ (0.12 × 72) = {sf((630 + 31.2) * 4 / 8.64)} J kg⁻¹ K⁻¹. (c) About 300 J kg⁻¹ K⁻¹: similar to tin or a brass-like alloy (well below aluminium\'s 900).',
  ['C1: water + calorimeter', 'A1: energy gained', 'C1: heat lost by metal', 'A1: c', 'B1: sensible identification'], aq='c')
N('H', 6, 'Hot coffee (0.20 kg, at 85 °C) is poured into a 0.30 kg ceramic mug (c = 850 J kg⁻¹ K⁻¹) at 20 °C. Treat coffee as water. (a) Calculate the common temperature, ignoring losses. (b) Calculate the energy transferred to the mug. (c) Explain why pre-warming the mug keeps the coffee hotter. Give only the answer to (a).' + WATER, (0.2 * CW * 85 + 0.3 * 850 * 20) / (0.2 * CW + 0.3 * 850), '°C',
  f'(a) θ = (0.20 × 4200 × 85 + 0.30 × 850 × 20) ÷ (0.20 × 4200 + 0.30 × 850) = {sf((71400 + 5100) / 1095)} °C. (b) 0.30 × 850 × ({sf((71400 + 5100) / 1095, 4)} − 20) = {sf(255 * ((71400 + 5100) / 1095 - 20))} J. (c) A warm mug takes less energy from the coffee, so the final temperature is higher.',
  ['M1: heat balance', 'C1: substitution', 'A1: θ', 'C1: energy to mug', 'A1: value', 'B1: less energy absorbed'], aq='θ')
N('H', 5, 'Two cups of water, A (0.25 kg at 70 °C) and B (0.15 kg at 10 °C), are mixed in an insulated jug. (a) Calculate the final temperature. (b) Calculate the energy transferred from A to B. (c) Explain, using molecular ideas, why heat flows from A to B and not the other way. Give only the answer to (a).' + WATER, (0.25 * 70 + 0.15 * 10) / 0.40, '°C',
  f'(a) θ = (0.25 × 70 + 0.15 × 10) ÷ 0.40 = {sf(19 / 0.4)} °C. (b) E = 0.25 × 4200 × (70 − {sf(47.5)}) = {sf(0.25 * 4200 * 22.5)} J. (c) A\'s molecules have the higher mean kinetic energy; in collisions energy is passed, on average, from faster to slower molecules until the mean energies are equal.',
  ['M1: weighted mean', 'A1: θ', 'C1: E = mcΔθ', 'A1: E', 'B1: molecular explanation'], aq='θ')
N('H', 6, 'A 0.50 kg block of steel (c = 450 J kg⁻¹ K⁻¹) at 20 °C and a 0.50 kg block of aluminium (c = 900 J kg⁻¹ K⁻¹) at 80 °C are placed together in an insulated box. (a) State which block\'s temperature changes more, and why. (b) Calculate the final temperature. (c) Calculate the energy transferred. Give only the answer to (b).', (0.5 * 450 * 20 + 0.5 * 900 * 80) / (0.5 * 450 + 0.5 * 900), '°C',
  f'(a) The steel: it has the smaller heat capacity, so the same energy gives a bigger temperature change. (b) θ = (225 × 20 + 450 × 80) ÷ (225 + 450) = {sf(40500 / 675)} °C. (c) E = 450 × (80 − 60) = 9000 J',
  ['B1: steel', 'B1: smaller heat capacity', 'M1: heat balance', 'A1: θ', 'C1: E = CΔθ', 'A1: 9000 J'], aq='θ')
N('H', 5, 'An electrically heated hot-water tank holds 150 kg of water at 60 °C. Overnight it cools to 48 °C. (a) Calculate the energy lost. (b) Calculate the average rate of heat loss over 10 hours. (c) Suggest how the tank could be modified to reduce the loss. Give only the answer to (b).' + WATER, 150 * CW * 12 / 36000, 'W',
  f'(a) E = 150 × 4200 × 12 = {sf(7.56e6)} J. (b) P = 7.56 × 10⁶ ÷ 36000 = {sf(7.56e6 / 36000)} W. (c) Thicker insulation (lagging) with low thermal conductivity, and reducing the surface area or temperature difference.',
  ['C1: E = mcΔθ', 'A1: E', 'C1: P = E/t with t in s', 'A1: P', 'B1: insulation'], aq='P')
N('H', 6, 'A metal sphere at 400 °C is dropped into an insulated container with 1.0 kg of water at 15 °C. The water rises to 25 °C, and 2.0 g of it boils away when the sphere enters. (a) Calculate the energy to warm the water. (b) Calculate the energy to boil the 2.0 g (it was effectively heated from 15 °C and boiled). (c) Calculate the heat capacity of the sphere. Give only the answer to (c).' + WATER + VAPOUR, (0.998 * CW * 10 + 0.002 * (CW * 85 + LV)) / (400 - 25), 'J K⁻¹',
  f'(a) 0.998 × 4200 × 10 = {sf(0.998 * 4200 * 10)} J. (b) 0.002 × (4200 × 85 + 2.26 × 10⁶) = {sf(0.002 * (4200 * 85 + LV))} J. (c) C = ({sf(0.998 * 4200 * 10, 4)} + {sf(0.002 * (4200 * 85 + LV), 4)}) ÷ (400 − 25) = {sf((0.998 * CW * 10 + 0.002 * (CW * 85 + LV)) / 375)} J K⁻¹',
  ['C1: water warming', 'A1: (a)', 'C1: heating and boiling the 2.0 g', 'A1: (b)', 'C1: C = E/Δθ', 'A1: C'], aq='C')

lesson('19.5')
N('H', 5, 'A digital thermometer uses a thermistor whose resistance is 3.3 kΩ at 25 °C and 1.1 kΩ at 60 °C. (a) Calculate the change in resistance per kelvin, assuming linearity. (b) Use it to estimate the temperature when R = 2.0 kΩ. (c) Express that temperature in kelvin. Give only the answer to (b).', 25 + (3.3 - 2.0) / ((3.3 - 1.1) / 35), '°C',
  f'(a) (3.3 − 1.1) ÷ 35 = {sf(2.2 / 35)} kΩ per K (a fall). (b) θ = 25 + (3.3 − 2.0) ÷ {sf(2.2 / 35, 4)} = {sf(25 + 1.3 / (2.2 / 35))} °C. (c) T = {sf(25 + 1.3 / (2.2 / 35), 4)} + 273 = {sf(25 + 1.3 / (2.2 / 35) + 273)} K',
  ['C1: gradient', 'A1: (a)', 'C1: interpolation', 'A1: θ', 'B1: kelvin'], aq='θ')
N('H', 6, 'A constant-volume gas thermometer bulb is at 273.16 K (triple point) with pressure 6.50 × 10⁴ Pa. It is placed in boiling sulfur and the pressure becomes 1.70 × 10⁵ Pa. (a) Calculate the temperature in kelvin. (b) Convert to °C. (c) Explain why the gas must be kept at low pressure for the scale to agree with the thermodynamic scale. Give only the answer to (a).', 273.16 * 1.70e5 / 6.50e4, 'K',
  f'(a) T = 273.16 × 1.70 × 10⁵ ÷ 6.50 × 10⁴ = {sf(273.16 * 1.7e5 / 6.5e4)} K. (b) θ = {sf(273.16 * 1.7e5 / 6.5e4, 4)} − 273.15 = {sf(273.16 * 1.7e5 / 6.5e4 - 273.15)} °C. (c) At low pressure the gas behaves ideally (molecules far apart, negligible forces), so p ∝ T exactly.',
  ['C1: T ∝ p', 'C1: substitution', 'A1: T', 'B1: °C', 'B1: ideal at low pressure', 'B1: reason'], aq='T')
N('H', 5, 'Interstellar dust grains are at about 15 K. The cosmic microwave background is at 2.7 K. (a) Express both in °C. (b) Calculate the ratio of the grain temperature to the background temperature. (c) Explain why this ratio has meaning in kelvin but not in °C. Give only the answer to (b).', 15 / 2.7, None,
  '(a) −258 °C and −270.45 °C. (b) ratio = 15 ÷ 2.7 = 5.6. (c) Ratios need a true zero: the kelvin scale starts at absolute zero, the Celsius scale does not.',
  ['A1: both conversions', 'C1: ratio in K', 'A1: 5.6', 'B1: absolute zero', 'B1: Celsius ratio meaningless'], sig=2, aq='ratio')
N('H', 6, 'A home-made thermometer uses the length of a mercury thread: 3.20 cm at the ice point and 18.60 cm at the steam point. In a sauna it reads 13.50 cm. (a) Calculate the sauna temperature on this thermometer\'s scale. (b) Convert to kelvin. (c) Explain why a reading of exactly 100 °C would not be obtained in boiling water at the top of a mountain. Give only the answer to (a).', (13.50 - 3.20) / (18.60 - 3.20) * 100, '°C',
  f'(a) θ = (13.50 − 3.20) ÷ (18.60 − 3.20) × 100 = {sf(10.3 / 15.4 * 100)} °C. (b) T = {sf(10.3 / 15.4 * 100, 4)} + 273 = {sf(10.3 / 15.4 * 100 + 273)} K. (c) Water boils below 100 °C at lower air pressure, so the "steam point" is lower there.',
  ['C1: interpolation', 'C1: substitution', 'A1: θ', 'B1: kelvin', 'B1: lower pressure', 'B1: lower boiling point'], aq='θ')

lesson('19.6')
N('H', 5, 'A 1.5 kW electric storage heater contains 40 kg of bricks (c = 840 J kg⁻¹ K⁻¹). It charges overnight from 20 °C to 220 °C. (a) Calculate the energy stored. (b) Calculate the charging time with no losses. (c) The bricks release this energy over 10 hours. Calculate the average heating power. Give only the answer to (c).', 40 * 840 * 200 / 36000, 'W',
  f'(a) E = 40 × 840 × 200 = {sf(6.72e6)} J. (b) t = 6.72 × 10⁶ ÷ 1500 = {sf(6.72e6 / 1500)} s. (c) P = 6.72 × 10⁶ ÷ 36000 = {sf(6.72e6 / 36000)} W',
  ['C1: E = mcΔθ', 'A1: E', 'A1: t', 'C1: P = E/t', 'A1: P'], aq='P')
N('H', 6, 'A steam iron uses 0.025 kg of water per minute, heating it from 20 °C and turning it all into steam at 100 °C. (a) Calculate the energy per minute to heat the water to 100 °C. (b) Calculate the energy per minute to vaporise it. (c) Calculate the minimum power of the iron\'s heater. Give only the answer to (c).' + WATER + VAPOUR, (0.025 * CW * 80 + 0.025 * LV) / 60, 'W',
  f'(a) 0.025 × 4200 × 80 = 8400 J. (b) 0.025 × 2.26 × 10⁶ = {sf(0.025 * LV)} J. (c) P = (8400 + {sf(0.025 * LV, 4)}) ÷ 60 = {sf((8400 + 0.025 * LV) / 60)} W',
  ['C1: mcΔθ', 'A1: (a)', 'C1: mL', 'A1: (b)', 'C1: per second', 'A1: P'], aq='P')
N('H', 5, 'Engineers compare two coolants for a computer: water (c = 4200 J kg⁻¹ K⁻¹) and oil (c = 1900 J kg⁻¹ K⁻¹). The processor produces 120 W and the coolant may warm by at most 8.0 K. (a) Calculate the mass flow rate of water needed. (b) Calculate the flow rate of oil needed. (c) State which is better and why. Give only the answer to (b).', 120 / (1900 * 8.0), 'kg s⁻¹',
  f'(a) ṁ = P/(cΔθ) = 120 ÷ (4200 × 8.0) = {sf(120 / 33600)} kg s⁻¹. (b) ṁ = 120 ÷ (1900 × 8.0) = {sf(120 / 15200)} kg s⁻¹. (c) Water: its higher c means less coolant must flow (but oil is used where water could short circuit).',
  ['C1: ṁ = P/cΔθ', 'A1: water', 'A1: oil', 'B1: water better', 'B1: higher c'], aq='ṁ')
N('H', 6, 'A 2.0 kg block of copper (c = 385 J kg⁻¹ K⁻¹) at 150 °C is placed on a large block of ice at 0 °C. (a) Calculate the energy the copper gives out cooling to 0 °C. (b) Calculate the mass of ice melted. (c) A 2.0 kg aluminium block (c = 900 J kg⁻¹ K⁻¹) at 150 °C is used instead. Calculate how many times more ice melts. Give only the answer to (b).' + FUSION, 2.0 * 385 * 150 / LF, 'kg',
  f'(a) E = 2.0 × 385 × 150 = {sf(115500)} J. (b) m = E/L = {sf(115500, 4)} ÷ 3.34 × 10⁵ = {sf(115500 / LF)} kg. (c) Ratio = 900 ÷ 385 = {sf(900 / 385)} times more ice.',
  ['C1: E = mcΔθ', 'A1: E', 'C1: m = E/L', 'A1: m', 'B1: ratio of c'], aq='m')
N('H', 5, 'Tea is made by pouring 0.25 kg of water at 100 °C onto tea leaves in a pot. Milk (0.030 kg at 5 °C, c = 3900 J kg⁻¹ K⁻¹) is then added. (a) Calculate the temperature of the tea after the milk is added, ignoring other losses. (b) Calculate the energy given to the milk. (c) Explain whether adding the milk earlier or later keeps the tea warmer after 10 minutes. Give only the answer to (a).' + WATER, (0.25 * CW * 100 + 0.030 * 3900 * 5) / (0.25 * CW + 0.030 * 3900), '°C',
  f'(a) θ = (0.25 × 4200 × 100 + 0.030 × 3900 × 5) ÷ (0.25 × 4200 + 0.030 × 3900) = {sf((105000 + 585) / 1167)} °C. (b) 0.030 × 3900 × ({sf((105000 + 585) / 1167, 4)} − 5) = {sf(117 * ((105000 + 585) / 1167 - 5))} J. (c) Adding milk early lowers the temperature, so the tea then loses heat more slowly; adding it early usually leaves the tea slightly warmer after 10 minutes.',
  ['M1: heat balance', 'A1: θ', 'C1: energy to milk', 'A1: value', 'B1: cooling rate depends on temperature difference'], aq='θ')
N('H', 6, 'An inventor claims a 70 kg person could boil 1.0 kg of water at 20 °C by running up stairs. (a) Calculate the energy needed to bring the water to the boil (100 °C). (b) Calculate the height the person would need to climb to gain that much gravitational potential energy. (c) Comment on the claim. Give only the answer to (b).' + WATER + take('g'), 1.0 * CW * 80 / (70 * 9.81), 'm',
  f'(a) E = 1.0 × 4200 × 80 = 336000 J. (b) h = E/(mg) = 336000 ÷ (70 × 9.81) = {sf(336000 / 686.7)} m. (c) That is a climb of about 490 m — possible, but the energy would have to be converted to heat with 100 % efficiency, which it cannot be; the body\'s own efficiency is about 25 %.',
  ['C1: E = mcΔθ', 'A1: E', 'C1: mgh = E', 'A1: h', 'B1: efficiency comment', 'B1: realistic conclusion'], aq='h')
N('H', 5, 'A student uses an electrical method on a 1.0 kg aluminium block and plots temperature against time. The straight part has gradient 0.045 K s⁻¹ with a 42 W heater. (a) Calculate c. (b) The accepted value is 900 J kg⁻¹ K⁻¹. Calculate the percentage error. (c) Suggest one reason for the error and how to reduce it. Give only the answer to (a).', 42 / (1.0 * 0.045), 'J kg⁻¹ K⁻¹',
  f'(a) c = P/(m × gradient) = 42 ÷ (1.0 × 0.045) = {sf(42 / 0.045)} J kg⁻¹ K⁻¹. (b) ({sf(42 / 0.045, 4)} − 900) ÷ 900 × 100 = {sf((42 / 0.045 - 900) / 9)} %. (c) Heat losses (or poor thermal contact): insulate the block and use oil in the thermometer hole.',
  ['C1: P = mc dθ/dt', 'A1: c', 'A1: percentage error', 'B1: reason', 'B1: improvement'], aq='c')
N('H', 6, 'A 0.050 kg ice cube at −10 °C is dropped into 0.30 kg of orange juice (treat as water) at 20 °C. c_ice = 2100 J kg⁻¹ K⁻¹. (a) Show that all the ice melts. (b) Calculate the final temperature. (c) Explain why ice at −10 °C cools a drink slightly more than the same mass of ice at 0 °C. Give only the answer to (b).' + WATER + FUSION, (0.3 * CW * 20 - 0.05 * CICE * 10 - 0.05 * LF) / (0.35 * CW), '°C',
  f'(a) Juice cooling to 0 °C can give 0.30 × 4200 × 20 = 25200 J. The ice needs 0.050 × 2100 × 10 + 0.050 × 3.34 × 10⁵ = 1050 + 16700 = 17750 J, which is less, so all the ice melts. (b) 0.30 × 4200 × (20 − θ) = 17750 + 0.050 × 4200 × θ: θ = (25200 − 17750) ÷ 1470 = {sf((25200 - 17750) / 1470)} °C. (c) It also absorbs energy warming from −10 °C to 0 °C before melting.',
  ['C1: energy available', 'C1: energy needed', 'A1: all melts', 'M1: energy balance', 'A1: θ', 'B1: extra energy to warm the ice'], aq='θ')

lesson('19.4')
N('M', 3, 'A 0.60 kg stone (c = 800 J kg⁻¹ K⁻¹) heated in a campfire is dropped into 2.0 kg of water at 15 °C. The water reaches 27 °C. Estimate the temperature of the campfire, assuming the stone reached it and no heat was lost.' + WATER, 27 + 2.0 * CW * 12 / (0.60 * 800), '°C',
  f'Heat gained by water = 2.0 × 4200 × 12 = 100800 J. 0.60 × 800 × (θ − 27) = 100800, so θ = 27 + 100800 ÷ 480 = {sf(27 + 100800 / 480)} °C', ['C1: heat gained by water', 'C1: heat balance', 'C1: rearranged'], aq='θ')
